/* Original Thai course. Examples and labs are instructional, not a hosted backend. */
export type Exercise =
 | {type:'mc';prompt:string;choices:string[];answer:number;why:string;hint:string}
 | {type:'text';prompt:string;answers:string[];why:string;hint:string}
 | {type:'order';prompt:string;steps:string[];why:string;hint:string}
 | {type:'sql';prompt:string;starter:string;solution:string;check:any;why:string;hint:string};
export type Example = {label:string;code:string;lines:string[]};
export type Chapter = {id:number;part:number;title:string;duration:number;lab?:string;lead:string;goals:string[];sections:{title:string;paragraphs:string[]}[];example:Example;extraCode?:Example;cases:string[];pitfall:string;exercises:Exercise[];refs:string[]};
const mc=(prompt:string,choices:string[],answer:number,why:string,hint:string):Exercise=>({type:'mc',prompt,choices,answer,why,hint});
const num=(prompt:string,answer:number|string,why:string,hint:string):Exercise=>({type:'text',prompt,answers:[String(answer)],why,hint});
const order=(prompt:string,steps:string[],why:string,hint:string):Exercise=>({type:'order',prompt,steps,why,hint});
const sq=(prompt:string,starter:string,solution:string,check:any,why:string,hint:string):Exercise=>({type:'sql',prompt,starter,solution,check,why,hint});
const sec=(title:string,...paragraphs:string[])=>({title,paragraphs});
const ex=(label:string,code:string,lines:string[]):Example=>({label,code,lines});
export const chapters:Chapter[]=[
{
id:1,part:1,title:'Backend คืออะไร และอะไรควรเชื่อถือ',duration:35,lab:'authority',
lead:'คุณเขียน C# ได้แล้ว ลองนึกถึงเกมที่ผู้เล่นมีไม้ 10 ชิ้น หากแก้ตัวแปรในเครื่องเป็น 999 แล้วเกมยอมให้สร้างบ้าน ใครเป็นคนตัดสินความจริงของเกม?',
goals:['แยกหน้าที่ Client, Server และ Database','เลือกข้อมูลที่ต้องให้ Server เป็นผู้ตัดสิน','แยกงานแสดงผลออกจากกฎที่มีผลต่อความคืบหน้า'],
sections:[
sec('1. Client คือเครื่องที่ผู้เล่นควบคุม','Unity บนมือถือหรือคอมเป็น Client ทำหน้าที่รับ input แสดง UI เล่นเสียงและแอนิเมชัน ผู้เล่นสามารถปิดเน็ต เปลี่ยนเวลา ดัดแปลงไฟล์ หรือส่ง HTTP เองได้ จึงใช้ค่าจาก Client เป็นหลักฐานว่าผู้เล่นมีสิทธิ์รับของไม่ได้','ปุ่ม Upgrade ส่งความตั้งใจว่าอยากอัปเกรด ส่วน Server ต้องหาผู้เล่นจาก token อ่านเลเวลและทรัพยากรจริง ตรวจราคา แล้วบันทึกผล Client ค่อยแสดงผลที่ได้รับกลับมา'),
sec('2. Server กับ Database ทำงานคนละหน้าที่','Server คือฝั่งที่เราเป็นผู้ควบคุมการทำงาน ส่วน Database จัดเก็บข้อมูลและบังคับกฎข้อมูล เช่น จำนวนห้ามติดลบ Supabase มี Auth, HTTP API และ PostgreSQL ให้ใช้ร่วมกัน Database Function ทำหน้าที่กฎเกมบางส่วนในฐานข้อมูลได้','คำว่า Backend รวมบริการเบื้องหลังเหล่านี้ ไม่จำเป็นต้องมีโปรเซส C# รันตลอดเวลา และไม่จำเป็นต้องใช้ Edge Function ทุก action ที่แก้ฐานข้อมูล'),
sec('3. ส่ง action แทนส่งผลลัพธ์','คำขอ {new_level: 10, wood: 999} ให้ผู้เล่นเป็นคนเสนอความจริงใหม่ คำขอ {recipe_id: "chair"} ให้ Server เป็นคนคำนวณผลตามกฎ คุณยังต้องตรวจว่า recipe นี้มีอยู่และเปิดให้ใช้ ไม่ใช่แค่เปลี่ยนชื่อ endpoint แล้วจะปลอดภัย','การอนุญาตให้จัดตำแหน่งเฟอร์นิเจอร์เองทำได้เมื่อ Server ตรวจความเป็นเจ้าของ ขอบเขต และเวอร์ชันข้อมูล ส่วนแอนิเมชันใบไม้ไหวอาจไม่ต้องส่งขึ้น Server เลย'),
sec('4. เลือกตามความต้องการของเกม','เกมเล่นคนเดียวที่ไม่มีเศรษฐกิจร่วมกันอาจยอมให้เซฟ offline ได้ ถ้ามีของซื้อขาย leaderboard หรือรางวัลที่มีมูลค่า ต้องกำหนดส่วนที่เชื่อถือ Server ชัดเจน การตัดสินใจนี้กำหนดทั้งต้นทุน request และประสบการณ์เมื่อเน็ตหลุด','หลักสูตรนี้กำหนดให้ทรัพยากรและความคืบหน้าถาวรเป็นข้อมูลที่ Server ตัดสิน ส่วน Client แสดงผลได้ทันทีแบบคาดการณ์ แต่ต้องปรับกลับหาก Server ปฏิเสธ')],
example:ex('สัญญาคำขอแบบ action · JSON',`POST /rest/v1/rpc/start_upgrade\n{ "p_request_id": "<UUID ของ action นี้>" }\n\n// response ที่ Server คำนวณ\n{ "level": 1, "status": "building", "wood": 0 }`,['Client ไม่ส่งราคาและเลเวลเป้าหมายที่เชื่อถือได้','Server ใช้ตัวตนจาก session และกฎจากฐานข้อมูล','request_id จะใช้ป้องกันผลซ้ำในบท 15']),
cases:['ร้านค้าออนไลน์: ลูกค้าส่งรหัสสินค้าและจำนวน ร้านค้าคำนวณราคากับส่วนลดเอง','ระบบจองห้อง: ผู้ใช้เลือกช่วงเวลา Server ตรวจว่ายังไม่มีการจองชนกัน'],
pitfall:'ซ่อนปุ่มหรือเข้ารหัสไฟล์เซฟช่วยด้าน UX หรือเพิ่มความยากในการแก้ไฟล์ แต่ไม่ได้บังคับสิทธิ์บน Server',
exercises:[mc('ข้อมูลใดควรให้ Server ตัดสินในเกมที่มีเศรษฐกิจร่วมกัน?',['ความดังเสียงเพลง','จำนวนเหรียญที่ได้รับจากเควสต์','สีขอบปุ่ม'],1,'รางวัลมีผลกับความคืบหน้าและเศรษฐกิจ จึงต้องตรวจบนฝั่งที่ผู้เล่นแก้โค้ดไม่ได้','คิดว่าถ้าแก้ค่านี้จะได้เปรียบผู้เล่นคนอื่นไหม'),mc('คำขออัปเกรดควรส่งอะไร?',['เงินคงเหลือหลังอัปเกรด','เลเวลใหม่พร้อมจำนวนไม้ใหม่','action และ request ID'],2,'Server อ่านข้อมูลจริงแล้วคำนวณราคาและผลเอง request ID ใช้จำ action','แยกสิ่งที่อยากทำออกจากผลที่อยากได้'),order('เรียงวงจรอัปเกรดที่ตรวจเงื่อนไข',['Client ส่ง action','Server ตรวจตัวตนและทรัพยากร','Database บันทึกผล','Client แสดงผลที่ได้รับ'],'UI ที่มั่นใจเกินไปก่อนบันทึกสำเร็จอาจแสดงสถานะไม่ตรงกับข้อมูลจริง','เริ่มจากความต้องการของผู้เล่น จบที่การแสดงผล')],refs:['functions']
},
{
id:2,part:1,title:'HTTP, REST และ JSON: อ่านภาษาของ API',duration:45,lab:'http',
lead:'API คือสัญญาการคุยกันผ่านเครือข่าย ก่อนเรียกจาก Unity เราควรอ่าน request หนึ่งอันแล้วรู้ว่ากำลังขออะไร ส่งในนามใคร และคำตอบหมายความว่าอย่างไร',
goals:['อ่าน method, URL, header และ body','เลือก GET กับ POST ตามงาน','แยกข้อผิดพลาดด้านเครือข่าย ตัวตน สิทธิ์ และกฎเกม'],
sections:[sec('1. Request มีส่วนประกอบอะไร','Method บอกลักษณะงาน เช่น GET สำหรับอ่าน URL ระบุปลายทางและ query เช่น select=username Header บอกชนิดข้อมูลหรือหลักฐานตัวตน Body เป็นข้อมูลที่ส่งสำหรับคำสั่ง เช่นพารามิเตอร์ RPC','JSON ใช้คู่ key/value String ต้องมีเครื่องหมายคำพูด Number และ boolean ไม่ต้องมี หลีกเลี่ยงต่อ JSON ด้วย string จาก input ให้ใช้ serializer เพื่อ escape ข้อมูลอย่างถูกต้อง'),sec('2. REST และ RPC อยู่ร่วมกันได้','Supabase Data API ให้เข้าถึงตารางผ่าน /rest/v1/profiles ส่วน /rest/v1/rpc/craft_chair เรียกฟังก์ชันบนฐานข้อมูล REST เหมาะกับอ่าน resource และ RPC เหมาะกับคำสั่งที่รวมกฎหลายขั้น','endpoint ที่ต่างกันไม่ได้ให้สิทธิ์ต่างกันโดยอัตโนมัติ สิทธิ์ตารางและสิทธิ์เรียก function ยังต้องออกแบบ GET ที่อ่านข้อมูลส่วนตัวต้องใช้ session เช่นเดียวกัน'),sec('3. API key ต่างจาก token ของผู้เล่น','publishable key ระบุแอปหรือโปรเจกต์ ส่งใน header apikey ส่วน Authorization: Bearer <access_token> ระบุผู้เล่นที่ Login แล้ว ห้ามใช้ publishable key รุ่นใหม่แทน user JWT ใน Bearer','Secret key หรือ service_role รุ่นเก่าให้สิทธิ์สูงและห้ามฝังใน Unity การทำให้ key ดูอ่านยากไม่ได้ทำให้เป็นความลับ เพราะเกมถูกแจกให้ผู้เล่น'),sec('4. อ่าน response ให้ครบ','2xx หมายถึงคำขอระดับ HTTP สำเร็จ 401 มักเกี่ยวกับหลักฐานตัวตนที่ใช้ไม่ได้ 403 มักเกี่ยวกับสิทธิ์ 429 ต้องลดความถี่ และ 5xx เป็นความล้มเหลวของบริการ ต้องอ่าน body และเอกสาร endpoint ด้วย เพราะ RPC บางแบบคืนผลธุรกิจใน JSON และบางแบบ raise error','timeout หมายถึง Client ไม่ได้คำตอบตามเวลา ไม่ได้พิสูจน์ว่า Server ไม่ทำงาน ห้าม retry การหักของแบบสุ่ม request ID ใหม่ ในบท 15 เราจะจัดการความไม่แน่นอนนี้')],
example:ex('อ่านโปรไฟล์ · HTTP',`GET https://<project>.supabase.co/rest/v1/profiles?select=username\napikey: <publishable key>\nAuthorization: Bearer <user access token>\n\n200 OK\n[{"username":"Mali"}]`,['query เลือกเฉพาะคอลัมน์ที่ใช้ ลดข้อมูลที่ส่ง','response ของการอ่านตารางเป็น array แม้เหลือหนึ่งแถว','RLS จะเป็นคนจำกัดว่าเห็นแถวใดได้']),
cases:['ระบบอากาศ: GET อ่านพยากรณ์ แต่ต้องคิด cache และ rate limit','ระบบสั่งอาหาร: POST สร้างออเดอร์ เมื่อ timeout ต้องตรวจผลเดิมก่อนสร้างซ้ำ'],pitfall:'status 200 กับ array ว่างอาจเป็นผลจาก RLS หรือไม่มีข้อมูล ไม่ใช่หลักฐานว่า Login ล้มเหลวเสมอไป',
exercises:[mc('ควรส่ง publishable key ไว้ที่ใด?',['Authorization แทน user JWT','header apikey','ในรหัสผ่านของผู้เล่น'],1,'apikey ระบุแอป user JWT ใน Authorization ระบุตัวตนผู้เล่น ทั้งสองอย่างมีหน้าที่ต่างกัน','นึกถึงบัตรของอาคารกับบัตรของคน'),num('response เป็น [{"quantity":8}] จำนวนไอเทมที่ต้องแสดงคือเท่าไร?',8,'อ่านค่าจาก quantity ใน object แรกของ array ไม่ใช่จำนวน object ใน array','มีหนึ่งแถว แต่แถวนี้ถือไอเทมหลายชิ้น'),mc('คำขอคราฟต์ timeout แล้ว ข้อสรุปใดถูกต้อง?',['Server ไม่หักของแน่นอน','อาจสำเร็จแล้ว แต่คำตอบสูญหาย','ส่งใหม่โดยเปลี่ยน action ID เสมอ'],1,'HTTP เป็นเครือข่ายที่คำตอบสูญหายได้ ต้องแยกการไม่ทราบผลจากการล้มเหลวของกฎเกม','Client เห็นเพียงฝั่งการรับคำตอบ')],refs:['keys','http']
},
{
id:3,part:1,title:'Schema: เปลี่ยนข้อมูลเกมให้เป็นความสัมพันธ์',duration:50,lab:'schema',
lead:'การเก็บทุกอย่างใน JSON ก้อนเดียวเริ่มได้เร็ว แต่เมื่อจะตรวจจำนวนของ ค้นหาผู้เล่น หรือแก้พร้อมกัน ต้องรู้ว่าข้อมูลชิ้นไหนมีตัวตนและสัมพันธ์กันอย่างไร',
goals:['เลือกชนิดข้อมูลและ key','ออกแบบหนึ่งต่อหนึ่งกับหนึ่งต่อหลาย','ใช้ composite key ป้องกันไอเทมซ้ำในกระเป๋า'],
sections:[sec('1. Table, row และ column','Table คือกลุ่มข้อมูลชนิดเดียว เช่น profiles Row คือหนึ่งระเบียน เช่นผู้เล่น Mali Column คือคุณสมบัติ เช่น username อย่าเก็บ player_1, player_2 เป็นคอลัมน์ เพราะจำนวนผู้เล่นเพิ่มได้ไม่จำกัด ควรเพิ่มแถวแทน','ข้อมูลนับชิ้นใช้ integer หรือ bigint เงินทศนิยมที่ต้องแม่นใช้ numeric หรือหน่วยย่อยแบบ integer UUID เหมาะกับรหัสผู้เล่น และ timestamptz ใช้แทนจุดเวลา ใน PostgreSQL มันเก็บ instant แล้วแสดงตาม timezone ของ session'),sec('2. Primary Key ระบุตัวตน','profiles.user_id เป็น PK อ้างถึง auth.users.id หนึ่งผู้เล่นมีโปรไฟล์หนึ่งแถว username อาจเปลี่ยนได้จึงไม่ควรใช้เป็นรหัสความสัมพันธ์ ความสัมพันธ์ที่ยึด user_id จะยังชี้ผู้เล่นเดิมหลังเปลี่ยนชื่อ','user_inventory ใช้ (user_id,item_id) เป็น PK สองคนมี wood ได้ แต่คนเดียวไม่ควรมีสองแถว wood สำหรับของแบบ stack ถ้าเป็นดาบแต่ละเล่มมีคุณสมบัติต่างกัน ให้มี instance_id ของแต่ละเล่ม'),sec('3. Foreign Key ป้องกันการอ้างถึงสิ่งที่ไม่มี','inventory.user_id อ้าง profiles.user_id และ inventory.item_id อ้าง item_catalog.id FK ปฏิเสธไอเทมหรือเจ้าของที่ไม่มีจริง ON DELETE CASCADE ลบลูกตามแม่ได้ เหมาะกับข้อมูลเฉพาะผู้เล่น แต่ต้องคิดก่อนใช้กับประวัติที่ต้องเก็บ','แยก catalog ที่บอกว่า wood ชื่ออะไรออกจาก inventory ที่บอกว่า Mali ถือกี่ชิ้น เปลี่ยนชื่อ wood ครั้งเดียวก็ถูกใช้กับทุกผู้เล่น'),sec('4. Normalize เท่าที่ปัญหาต้องการ','แยกข้อมูลซ้ำที่มีความหมายและเจ้าของชัดเจน ไม่จำเป็นต้องแยกทุกตัวเลขเป็นตารางใหม่ Layout เฟอร์นิเจอร์อาจเริ่มเป็น jsonb ถ้ามักอ่านทั้งชุด แต่ inventory ควรแยกแถวเพื่อหักจำนวนและตรวจ FK ได้ง่าย','วาดความสัมพันธ์ก่อนเขียน SQL: auth.users → profiles → shelters และ user_inventory; item_catalog → user_inventory ค่อยเพิ่มตารางเมื่อต้องเก็บข้อมูลชนิดใหม่จริง')],
example:ex('โครงสร้าง Inventory · PostgreSQL',`create table public.user_inventory (\n  user_id uuid references public.profiles(user_id) on delete cascade,\n  item_id text references public.item_catalog(id),\n  quantity bigint not null default 0 check (quantity >= 0),\n  primary key (user_id, item_id)\n);`,['PK ทำให้ทั้ง user_id และ item_id เป็น NOT NULL ด้วย','FK ต้องสร้าง profiles และ item_catalog ก่อน','CHECK บังคับจำนวน แต่ยังต้องมีสิทธิ์และกฎรับของ']),cases:['ร้านค้า: products เป็น catalog, order_items เป็นจำนวนสินค้าที่อยู่ในแต่ละออเดอร์','ห้องเรียน: students กับ courses เชื่อมผ่าน enrollments ที่ใช้คู่ student_id/course_id'],pitfall:'อย่าใช้ชื่อผู้เล่นเป็น FK และอย่าใช้จำนวนไอเทมเป็น ID ทั้งสองอย่างเปลี่ยนได้',
exercises:[mc('PK ของกระเป๋าของแบบ stack ควรเป็นอะไร?',['item_id อย่างเดียว','(user_id,item_id)','quantity'],1,'ใช้ item_id เดี่ยวจะห้ามผู้เล่นอื่นมีไอเทมเดียวกัน ใช้คู่จะห้ามซ้ำเฉพาะภายในเจ้าของ','ต้องยอมให้คนละคนมี wood เหมือนกัน'),mc('ดาบสองเล่มค่า durability ต่างกันควรเก็บอย่างไร?',['รวม quantity=2 แล้วทิ้ง durability','แถวละ instance_id และเจ้าของ','เพิ่มคอลัมน์ sword1 ถึง sword999'],1,'ไอเทมมีตัวตนเฉพาะต้องมีระเบียนเฉพาะ ความสัมพันธ์ยังใช้ user_id ได้','สองเล่มนี้ใช้แทนกันได้ทุกกรณีหรือไม่'),sq('เขียน query อ่าน item_id และ quantity ของ A จาก inventory เรียง item_id','SELECT ... FROM inventory ...;','SELECT item_id, quantity FROM inventory WHERE user_id = \'A\' ORDER BY item_id;',{kind:'result',values:[['stone',4],['wood',10]]},'WHERE จำกัดเจ้าของ ORDER BY ทำให้ลำดับผลแน่นอน แบบฝึกนี้ใช้ชื่อ inventory ในฐานข้อมูลฝึก','เลือกสองคอลัมน์ และกรอง user_id = \'A\'')],refs:['constraints']
},
{
id:4,part:1,title:'SQL อ่านข้อมูล: SELECT, JOIN และ GROUP BY',duration:65,lab:'sql',
lead:'SQL เป็นภาษาบอกว่าต้องการข้อมูลอะไร คุณไม่ต้องเขียน foreach เพื่อเชื่อมข้อมูลทีละผู้เล่น ลองอ่าน query เป็นขั้น: เอาจากไหน กรองอะไร และส่งคอลัมน์ไหนกลับ',
goals:['เขียน query ที่อ่านเฉพาะข้อมูลที่ต้องใช้','เชื่อมชื่อไอเทมกับจำนวนผ่าน JOIN','สรุปข้อมูลด้วย aggregate โดยไม่สับสนกับจำนวนแถว'],
sections:[sec('1. SELECT และ WHERE','SELECT item_id,quantity FROM inventory WHERE user_id=\'A\' เลือกสองคอลัมน์จากแถวของ A AND รวมเงื่อนไขที่ต้องจริงพร้อมกัน OR ใช้เมื่อจริงอย่างใดอย่างหนึ่ง NULL หมายถึงไม่มีค่า ใช้ IS NULL ไม่ใช่ = NULL','ใช้ parameter ในแอปหรือ function สำหรับ input อย่าต่อ SQL ด้วยชื่อที่ผู้ใช้พิมพ์ เพราะอาจเปลี่ยนความหมาย query ช่องฝึกในเว็บนี้ทำงานกับฐานข้อมูลเล่นในหน่วยความจำเท่านั้น'),sec('2. ORDER BY และ LIMIT','ฐานข้อมูลไม่รับประกันลำดับแถวหากไม่มี ORDER BY ต้องระบุ DESC ถ้าต้องการมากไปน้อย LIMIT ลดจำนวนผล เช่นรายการล่าสุด 20 แถว ถ้าค่าที่เรียงเท่ากัน เพิ่ม key ที่ไม่ซ้ำเพื่อให้ลำดับแน่นอน','การแบ่งหน้าด้วย offset เริ่มง่าย แต่ข้อมูลจำนวนมากหรือเพิ่มถี่อาจเหมาะกับ cursor เช่นใช้ created_at และ id เป็นจุดเริ่มหน้าใหม่ ไม่ควรโหลดประวัติทั้งหมดทุกครั้งที่เปิดเกม'),sec('3. JOIN เชื่อมด้วย key','inventory มี item_id ส่วน items มี name INNER JOIN items ON inventory.item_id=items.id เพิ่มชื่อให้แต่ละแถวที่ match LEFT JOIN เก็บแถวฝั่งซ้ายแม้ไม่มี match แล้วฝั่งขวาเป็น NULL','JOIN ที่ไม่มีเงื่อนไขถูกต้องอาจทำให้จำนวนแถวทวีคูณ ถ้ามี inventory 3 แถวและ catalog 4 แถว cross join ได้ 12 แถว ต้องตรวจ key ที่เชื่อมทุกครั้ง'),sec('4. COUNT, SUM และ GROUP BY','COUNT(*) นับแถว SUM(quantity) รวมจำนวนชิ้น การถือ wood 10 กับ stone 4 เท่ากับ 2 แถวแต่ 14 ชิ้น GROUP BY user_id แบ่งกลุ่มก่อนรวม HAVING กรองผลหลังรวม','SQLite ในช่องฝึกใช้สอนส่วนที่ร่วมกับ PostgreSQL แต่ไม่ได้รัน auth.uid(), jsonb, timestamptz หรือ row lock ของ PostgreSQL การอ่าน query ตรงนี้เป็นพื้นฐาน ก่อนนำไปใช้กับ Supabase จริง')],
example:ex('รวมชื่อกับจำนวน · SQL',`SELECT i.user_id, c.name, i.quantity\nFROM inventory AS i\nJOIN items AS c ON c.id = i.item_id\nWHERE i.user_id = 'A'\nORDER BY i.quantity DESC;\n\nSELECT user_id, SUM(quantity) AS total\nFROM inventory GROUP BY user_id;`,['AS ตั้งชื่อย่อ ไม่ได้แก้ชื่อตารางจริง','ON บอกวิธีจับคู่ WHERE บอกแถวที่ต้องการ','SUM รวมชิ้น COUNT นับระเบียน']),cases:['รายงานยอดขาย: JOIN order_items กับ products แล้ว SUM ราคาที่บันทึกตอนขาย','ระบบค้นหาเอกสาร: กรองเจ้าของและเรียงวันที่ แบ่งหน้าผลลัพธ์'],pitfall:'SELECT * อาจส่งข้อมูลมากเกินจำเป็น และจำนวนแถวหลัง JOIN อาจเพิ่มขึ้นตามความสัมพันธ์',
exercises:[sq('อ่าน item_id และ quantity เฉพาะ A ที่มี quantity >= 5 เรียง item_id','SELECT item_id, quantity FROM inventory;','SELECT item_id, quantity FROM inventory WHERE user_id=\'A\' AND quantity >= 5 ORDER BY item_id;',{kind:'result',values:[['wood',10]]},'A มี stone 4 และ wood 10 กรอง >=5 จึงเหลือ wood แถวเดียว','เพิ่ม WHERE ที่ตรวจทั้งเจ้าของและจำนวน'),sq('รวมจำนวนชิ้นของ B ให้ได้หนึ่งคอลัมน์หนึ่งแถว','SELECT ... FROM inventory;','SELECT SUM(quantity) FROM inventory WHERE user_id=\'B\';',{kind:'result',values:[[8]]},'B มี wood 3 กับ seed 5 รวมเป็น 8 การ COUNT จะได้ 2','ใช้ SUM(quantity)'),sq('อ่านชื่อไอเทมและจำนวนของ A เรียงชื่อ โดย JOIN inventory กับ items','SELECT ... FROM inventory i JOIN items c ON ...;','SELECT c.name, i.quantity FROM inventory i JOIN items c ON c.id=i.item_id WHERE i.user_id=\'A\' ORDER BY c.name;',{kind:'result',values:[['Stone',4],['Wood',10]]},'จับ item_id เข้ากับ id ของ catalog จึงอ่าน name ได้โดยไม่คัดลอกชื่อลง inventory','เลือก c.name, i.quantity และตรวจ key ของทั้งสองตาราง')],refs:['sql']
},
{
id:5,part:1,title:'SQL เขียนข้อมูลและ Constraints',duration:55,lab:'sql',
lead:'การเขียนข้อมูลที่ถูกต้องไม่ใช่แค่ UPDATE ได้ ต้องคิดว่าหากส่งค่าผิด ลืม WHERE หรือส่งข้อมูลเดิมซ้ำ ฐานข้อมูลจะยอมบันทึกอะไร',
goals:['ใช้ INSERT, UPDATE และ DELETE อย่างเจาะจง','ออกแบบ CHECK, UNIQUE และ NOT NULL','แยกความถูกต้องของข้อมูลออกจากสิทธิ์ทำ action'],
sections:[sec('1. INSERT เพิ่มแถว UPDATE แก้แถว DELETE ลบแถว','INSERT ระบุคอลัมน์ให้ชัดเพื่อไม่ผูกกับลำดับคอลัมน์ UPDATE ต้องมี WHERE ตาม key ที่ต้องการแก้ ถ้าไม่มี WHERE จะกระทบทุกแถว DELETE ก็เช่นกัน ก่อนแก้ข้อมูลจำนวนมาก ลอง SELECT ด้วย WHERE เดียวกันก่อน','UPDATE quantity=quantity+2 ให้ฐานข้อมูลคำนวณจากค่าปัจจุบัน ต่างจาก Client อ่าน 10 แล้วส่ง quantity=12 ซึ่งอาจทับการแก้ของคนอื่น'),sec('2. Constraints เป็นด่านข้อมูล','NOT NULL ห้ามไม่มีค่า CHECK(quantity>=0) ห้ามจำนวนติดลบ UNIQUE หรือ PK ห้าม key ซ้ำ FK ห้ามอ้างเจ้าของหรือชนิดของที่ไม่มี CHECK อย่างเดียวไม่ห้าม NULL เพราะผลที่ไม่เป็น false อาจผ่านได้ จึงต้องใช้ NOT NULL ร่วมด้วย','constraints ช่วยบังคับข้อมูลจากทุกช่องทาง รวมโค้ดหลังบ้าน แต่ไม่ได้พิสูจน์ว่าผู้เล่นหา wood 100 ชิ้นมาอย่างถูกกฎ RLS และ RPC ยังจำเป็น'),sec('3. Upsert กับความหมายของการซ้ำ','INSERT ... ON CONFLICT ... DO UPDATE รวมการเพิ่มกับแก้ตาม unique key เช่นเมื่อได้ wood เพิ่ม ให้เพิ่ม quantity ของแถวเดิม แต่การ upsert ไม่ได้กันรางวัลซ้ำ ถ้ากดรับสองครั้งแล้วบวกสองครั้งก็ยังซ้ำได้','เลือกว่าต้องแทนค่าเดิมหรือบวกจำนวน EXCLUDED.quantity คือค่าที่กำลังเสนอ insert ใน PostgreSQL ควรอ่านเงื่อนไข conflict ให้สัมพันธ์กับ key ที่ออกแบบ'),sec('4. การลบเป็นส่วนหนึ่งของแบบข้อมูล','DELETE ลบข้อมูลจริง soft delete เก็บ deleted_at เพื่อซ่อนจากการใช้งานและกู้คืนได้ แต่ทุก query ที่เกี่ยวข้องต้องคิดเงื่อนไขนี้ ON DELETE CASCADE สะดวกแต่ทำให้ลบลูกได้จำนวนมาก','ในช่องฝึกของบทนี้จะสร้างฐานข้อมูลใหม่ทุกครั้งที่ตรวจแบบฝึก จึงลองแก้ผิดได้โดยไม่กระทบผู้เล่นจริง งาน production ต้องใช้ migration และสำรองข้อมูลตามความเสี่ยง')],
example:ex('แก้จำนวนแบบมีเงื่อนไข · SQL',`UPDATE inventory\nSET quantity = quantity - 6\nWHERE user_id = 'A' AND item_id = 'wood'\n  AND quantity >= 6;\n\n-- ตรวจแถวที่แก้: ถ้าเป็น 0 แปลว่าข้อมูลไม่ตรงเงื่อนไข\nSELECT quantity FROM inventory\nWHERE user_id='A' AND item_id='wood';`,['เงื่อนไข quantity ป้องกันการหักมากกว่าที่มีใน statement นี้','ต้องตรวจ affected rows ก่อนให้ผลผลิต','ของหลายชนิดและผลผลิตต้องรวมใน transaction']),cases:['คลังสินค้า: บังคับ stock >=0 และใช้ key สินค้า/สาขา','ระบบสมาชิก: UNIQUE email ป้องกันบัญชีซ้ำตามกฎที่กำหนด'],pitfall:'UPDATE สำเร็จโดยแก้ 0 แถวได้ อย่าคิดว่าทุกคำสั่งที่ไม่ error ทำ action สำเร็จแล้ว',
exercises:[sq('เพิ่ม wood ให้ A อีก 2 ชิ้น ห้ามเปลี่ยนแถวอื่น','UPDATE inventory SET ... WHERE ...;','UPDATE inventory SET quantity=quantity+2 WHERE user_id=\'A\' AND item_id=\'wood\';',{kind:'state',query:'SELECT user_id,item_id,quantity FROM inventory ORDER BY user_id,item_id',values:[['A','stone',4],['A','wood',12],['B','seed',5],['B','wood',3]]},'ใช้ quantity+2 และระบุทั้ง owner และ item จึงไม่แก้ wood ของ B','WHERE ต้องใช้ทั้ง user_id และ item_id'),mc('CHECK(quantity>=0) อย่างเดียวเพียงพอจะห้าม NULL หรือไม่?',['เพียงพอ','ต้องใช้ NOT NULL ด้วย','ต้องใช้ JOIN'],1,'CHECK ไม่ใช่ NOT NULL ควรประกาศทั้งคู่เพื่อกำหนดความหมายข้อมูลให้ชัด','NULL ไม่ใช่จำนวนติดลบ'),sq('หัก stone ของ A 3 ชิ้นเมื่อมีพอ ห้ามแก้ผู้เล่น B','UPDATE inventory ...;','UPDATE inventory SET quantity=quantity-3 WHERE user_id=\'A\' AND item_id=\'stone\' AND quantity>=3;',{kind:'state',query:'SELECT quantity FROM inventory WHERE user_id=\'A\' AND item_id=\'stone\'',values:[[1]]},'A เริ่ม stone=4 จึงเหลือ 1 ในงานจริงยังต้องตรวจ affected rows ก่อนแจกของ','ใส่เงื่อนไข quantity >=3 และคำนวณจากค่าเดิม')],refs:['constraints']
},
{
id:6,part:1,title:'Transaction, Race Condition และ Lock',duration:65,lab:'race',
lead:'ผู้เล่นมีไม้ 10 ชิ้น เก้าอี้ใช้ไม้ 6 ชิ้น ถ้าคำขอ A และ B อ่าน 10 พร้อมกัน ทั้งคู่คิดว่าคราฟต์ได้ แล้วใครป้องกันไม่ให้ได้เก้าอี้สองตัว?',
goals:['อธิบาย atomicity กับ concurrency แยกกัน','เลือก conditional update หรือ row lock','รู้ว่าควร rollback และ retry เมื่อไร'],
sections:[sec('1. Transaction ทำให้การเปลี่ยนหลายขั้นเป็นชุด','BEGIN เปิด transaction COMMIT ยืนยัน ROLLBACK ย้อนชุด เช่นหักไม้แล้วเพิ่มเก้าอี้ ถ้าเพิ่มเก้าอี้ล้มเหลวต้องย้อนการหักด้วย มิเช่นนั้นผู้เล่นเสียของแต่ไม่ได้ผลผลิต','การเรียก Database Function ผ่าน RPC เป็นหนึ่งคำสั่งฐานข้อมูลและทำงานใน transaction ของคำขอนั้น หาก raise exception ที่ไม่ถูกกลืน การเปลี่ยนของคำขอถูก rollback ไม่ต้องรอให้ Unity สั่ง undo'),sec('2. Atomic ไม่ได้แปลว่าปลอด race ทุกแบบ','สอง transaction ยังอ่านค่าเดียวกันได้หากไม่ได้ล็อกอย่างเหมาะสม ตัวอย่างอ่าน quantity=10 แล้วทั้งสองเขียน quantity=4 อาจจบไม้=4 แต่ได้เก้าอี้=2 เรียก lost update การมี BEGIN อย่างเดียวไม่แก้ทุกปัญหา','conditional UPDATE quantity=quantity-6 WHERE quantity>=6 พร้อมตรวจ affected rows ช่วยให้การตรวจและหักอยู่ statement เดียว หากต้องตรวจหลายแถว ให้ใช้ lock และกฎลำดับการล็อกที่สม่ำเสมอ'),sec('3. SELECT FOR UPDATE ใน PostgreSQL','มันล็อกแถวที่อ่านเพื่อให้ผู้เขียนหรือผู้ขอล็อกแถวเดียวกันรอจน transaction จบ จากนั้นผู้รอต้องอ่านและตรวจจากค่าล่าสุด ไม่ใช่ใช้ค่าที่อ่านไว้ก่อนล็อก แบบจำลองข้างล่างแสดงสองแนวทางนี้ทีละจังหวะ','เพื่อให้อธิบายง่าย หลักสูตรตัวอย่างบาง action ล็อกแถว profiles ของเจ้าของก่อนแก้ข้อมูลเกม ถือเป็นคิวต่อผู้เล่น ใช้ได้เมื่อทุก action ที่เกี่ยวข้องใช้ lock เดียวกัน ห้ามมีอีกเส้นทางหนึ่งเขียนข้ามกติกานี้'),sec('4. Deadlock และช่วงเวลาที่ถือ lock','ถ้า A ล็อกไม้แล้วรอหิน ขณะที่ B ล็อกหินแล้วรอไม้ เกิด deadlock PostgreSQL ยกเลิก transaction หนึ่งตัว วิธีลดคือเรียง key ที่ล็อกให้เหมือนกัน ถือ lock สั้น และไม่รอการตอบของผู้เล่นกลาง transaction','SQLite ในเว็บไม่รองรับ PostgreSQL FOR UPDATE และไม่จำลอง concurrent transaction สอง connection แบบนี้ ตัวทดลอง race เป็นแบบจำลองลำดับเหตุการณ์ แยกจากช่องรัน SQL จริง')],
example:ex('ล็อกก่อนอ่านเพื่อใช้ค่าใหม่ · PostgreSQL',`begin;\nselect quantity from public.user_inventory\nwhere user_id = '<UUID>' and item_id = 'wood'\nfor update;\n-- ตรวจ quantity ที่อ่านหลังได้ lock แล้ว\n-- หัก wood และเพิ่ม chair ภายใน transaction เดียว\ncommit;`,['โค้ดนี้เป็นโครงร่าง ยังต้องใส่การตรวจและการแก้ข้อมูล','ถ้าเงื่อนไขไม่ผ่านให้ raise error/rollback','ตัวอย่าง RPC ที่รวมกฎจะอยู่บท 14']),cases:['การจองที่นั่ง: สองคนพยายามจองที่นั่งสุดท้าย','โอนเครดิต: หักบัญชีต้นทางและเพิ่มปลายทางต้องสำเร็จทั้งคู่'],pitfall:'การปิดปุ่มใน Unity ลดการกดซ้ำ แต่คนสองเครื่องหรือ request ที่ส่งตรงยังชนกันได้',
exercises:[num('ไม้ 10 ชิ้น เก้าอี้ใช้ 6 ชิ้น ระบบที่ถูกต้องคราฟต์สำเร็จได้สูงสุดกี่ครั้ง?',1,'ครั้งแรกเหลือ 4 จึงไม่พอสำหรับครั้งที่สอง แม้คำขอเริ่มพร้อมกัน','คิดจากทรัพยากรที่เหลือหลัง action แรก'),mc('สิ่งใดจริงเกี่ยวกับ transaction?',['มี BEGIN แล้วไม่เกิด race ใด ๆ','รวมการบันทึกเป็นชุด แต่ยังต้องควบคุมการอ่านเขียนพร้อมกัน','ใช้แทนการตรวจตัวตนได้'],1,'Atomicity กับ isolation/concurrency เป็นปัญหาคนละส่วน ใช้ lock หรือ conditional write ให้เหมาะ','ลองคิดถึงสองคนที่อ่านค่าก่อนอีกคนเขียน'),order('เรียง action ที่ใช้ lock ต่อผู้เล่น',['ตรวจ auth.uid()','ล็อกแถวผู้เล่น','อ่านและตรวจทรัพยากรล่าสุด','หักของและเพิ่มผลผลิต','commit และคืนผล'],'ต้องอ่านข้อมูลที่ใช้ตัดสินหลังได้ lock และห้ามคืนผลสำเร็จก่อนชุดการบันทึกสำเร็จ','ใครเป็นผู้เล่นต้องรู้ก่อนเลือกแถวที่จะล็อก')],refs:['locks','functions']
},
{
id:7,part:2,title:'Supabase: โปรเจกต์แรกและ Migration',duration:55,lab:null,
lead:'ถึงจุดนี้คุณรู้ว่าต้องเก็บอะไรและอ่านเขียนอย่างไร บทนี้จัดเครื่องมือให้ทำซ้ำได้ การแก้ SQL ใน Dashboard สะดวก แต่ถ้าไม่เก็บที่มา คุณจะสร้างระบบเดิมใหม่ได้ยาก',
goals:['แยก Auth, Data API, PostgreSQL และ Edge Functions','สร้างโครงสร้างตามลำดับ FK','เก็บ schema และ grants เป็น migration'],
sections:[sec('1. บริการที่เราจะใช้','Supabase Auth ดูแลบัญชีและ session PostgreSQL เก็บตารางและ functions Data API แปลง HTTP เป็นการอ่านตารางหรือเรียก RPC Edge Functions ใช้เมื่อต้องคุยกับบริการภายนอกหรือทำงานฝั่ง server ที่ไม่เหมาะอยู่ใน SQL','Realtime และ Storage ไม่จำเป็นสำหรับทุกเกม cozy อย่าเปิดหรือเรียกเพิ่มเพียงเพราะมีให้ใช้ เป้าหมายรอบแรกคือ Login → อ่านข้อมูล → ส่ง action → ได้ผลที่ตรวจแล้ว'),sec('2. ขั้นตอนโปรเจกต์แรกจริง','เปิด Dashboard สร้างโปรเจกต์ development เลือก region ที่เหมาะกับผู้เล่น จด Project URL และ publishable key จาก Connect/API Keys ตั้ง Anonymous sign-in ใน Auth เมื่อต้องเริ่ม Guest แล้วเข้า SQL Editor','สร้าง profiles ก่อน item_catalog แล้ว inventory และ shelters ตามความสัมพันธ์ ทุกตารางที่อยู่ใน exposed schema ต้องกำหนด grants และ RLS ให้ตรงกับงาน อย่าเปิดให้เขียนเพื่อให้เดโมผ่านแล้วลืมปิด'),sec('3. Migration คือประวัติโครงสร้าง','ไฟล์ migration เป็น SQL ที่มีลำดับ เช่น 001_initial.sql, 002_add_ready_at.sql ใช้สร้างหรือเปลี่ยน Schema รวมถึงสิทธิ์และ policy ควรเก็บใน version control เพื่อรู้ว่ารุ่นไหนใช้กฎอะไร','งานเรียนเริ่มด้วย SQL Editor ได้ แต่เก็บ SQL ที่รันทุกครั้งเป็นไฟล์ก่อน อย่าแก้ไฟล์เก่าที่ใช้ production แล้ว ให้เพิ่ม migration ใหม่และวางแผน backfill ถ้าคอลัมน์ใหม่ต้องมีค่าในแถวเก่า'),sec('4. Local development ต่างจาก production','Supabase CLI ช่วยรันสภาพแวดล้อม local และจัด migration โดยต้องมีเครื่องมือที่รองรับ ตรวจขั้นติดตั้งจากเอกสารทางการที่ลิงก์ไว้ local stack สำหรับพัฒนาไม่ควรเปิดสู่ผู้ใช้จริงโดยตรง','แยก development กับ production เพื่อไม่ให้แบบฝึกหรือการ reset ฐานข้อมูลแตะผู้เล่นจริง ก่อนย้ายเครื่องหรือ self-host ต้องวางการย้าย DB, Auth, config, secret, backup และปลายทาง API ไม่ใช่แค่คัดลอก schema')],
example:ex('migration เริ่มต้นของโปรไฟล์ · PostgreSQL',`create table public.profiles (\n  user_id uuid primary key references auth.users(id) on delete cascade,\n  username text not null default 'New player',\n  created_at timestamptz not null default now()\n);\nalter table public.profiles enable row level security;\nrevoke all on public.profiles from anon, authenticated;\n-- บท 10 จะเพิ่ม grant และ policy สำหรับอ่าน`,['auth.users มาจาก Supabase Auth','ช่วงนี้ยังไม่มีสิทธิ์ Client อ่านหรือเขียน เป็นค่าเริ่มต้นก่อนเปิดตามงาน','ไม่ได้สร้าง profile อัตโนมัติจนกว่าจะเพิ่ม trigger ในบท 10']),cases:['เว็บสมาชิก: migration ใช้เพิ่ม subscription tier และ policy','ระบบบริษัทหลายสาขา: development ใช้ข้อมูลจำลอง แยก production ที่มีข้อมูลจริง'],pitfall:'CREATE TABLE สำเร็จไม่เท่ากับ API เข้าถึงได้ ต้องตรวจทั้ง grants และ RLS',
exercises:[order('เรียงลำดับตารางตาม FK',['profiles อ้าง auth.users','item_catalog เก็บชนิดของ','user_inventory อ้าง profiles และ item_catalog'],'FK ต้องมีตารางปลายทางก่อน มิฉะนั้น migration จะล้มเหลว','มองจากตารางแม่ไปตารางลูก'),mc('ควรทำอย่างไรกับการเพิ่มคอลัมน์ใน production?',['แก้ migration เก่าและหวังว่าทุกเครื่องตรงกัน','เพิ่ม migration ใหม่และวางแผนข้อมูลแถวเก่า','ลบ DB แล้วสร้างใหม่'],1,'ประวัติที่รันแล้วต้องอธิบายได้ migration ใหม่ทำให้สภาพแวดล้อมตามทันโดยไม่สูญข้อมูล','คิดถึงคนที่เปิดโปรเจกต์ใหม่จาก repository'),mc('บริการใดตัดสิน craft ที่อ่านเขียนข้อมูลหลายตารางได้โดยตรง?',['Database Function ผ่าน RPC','Storage bucket','UI Canvas ของ Unity'],0,'Database Function รันภายใน PostgreSQL เหมาะกับ transaction ที่เกี่ยวกับข้อมูล','การคุย HTTP ไม่จำเป็นต้องผ่าน Edge Function ทุกครั้ง')],refs:['migrations','selfhost']
},
];
chapters.push(
{
id:8,part:2,title:'Auth I: Guest, สมัครบัญชี และ Login',duration:60,lab:'auth',
lead:'Auth ยืนยันว่าใครกำลังใช้งาน แต่ไม่ได้บอกว่าคนนั้นมีสิทธิ์รับรางวัลหรือแก้ของได้ทุกอย่าง บทนี้สร้างความเข้าใจตัวตนก่อนทำเรื่องสิทธิ์',
goals:['แยก authentication จาก authorization','เข้าใจ Guest user และ anonymous role','วาง flow สมัครบัญชี Login Logout และลืมรหัสผ่าน'],
sections:[sec('1. Authentication ถามว่าใคร','Supabase Auth ออก user ID ที่ใช้ผูกโปรไฟล์และข้อมูลเกม Password, Magic Link และ OAuth เป็นวิธีพิสูจน์ตัวตน การเปลี่ยนชื่อที่แสดงในเกมไม่เปลี่ยน user ID และ email ที่ส่งเองใน body ไม่ใช่หลักฐานว่าผู้ส่งเป็นเจ้าของ email','Authorization ถามว่าคนนี้ทำอะไรได้ เช่น Mali Login แล้วแต่ยังไม่มีสิทธิ์อ่านของผู้เล่น B การตรวจตัวตนสำเร็จจึงเป็นเพียงจุดเริ่มของการตรวจ action'),sec('2. Guest ก็มีตัวตน','Anonymous sign-in สร้าง user ID และ session จริง ผู้ใช้ชนิดนี้เข้าฐานข้อมูลด้วย role authenticated เช่นผู้ใช้ทั่วไป ต่างจาก role anon ของคำขอที่ยังไม่ Login ต้องเปิด Anonymous sign-in ใน Dashboard ก่อน','Guest เล่นต่อได้เมื่อยังมี session ที่กู้ใช้ได้ แต่หากล้างข้อมูลแอป ออกจากระบบ หรือเปลี่ยนเครื่องและยังไม่ได้ผูก identity ถาวร จะไม่มีวิธี Login กลับด้วย email/password ต้องแจ้งข้อจำกัดนี้ก่อนผู้เล่นสะสมของมาก'),sec('3. Email/Password และการยืนยัน','สมัครส่ง email/password ไป Auth service ไม่สร้างคอลัมน์เก็บ password ใน profiles เมื่อเปิด email confirmation การสมัครอาจยังไม่มี session ต้องรอผู้ใช้ยืนยันก่อน Login ตรวจทั้ง error และ session ที่ได้รับ','สำหรับ Unity เริ่มด้วย Email/Password เข้าใจง่ายกว่า Magic Link ซึ่งต้องจัด redirect/deep link และส่งผู้ใช้กลับเข้าเกม ส่วน OAuth ต้องตั้งค่าผู้ให้บริการและ callback เพิ่ม สามารถต่อยอดหลัง flow หลักทำงาน'),sec('4. Logout และลืมรหัสผ่าน','Logout ล้าง session ในแอปและเรียกบริการเพื่อจบ session ตาม scope ที่เลือก อย่าเพียงเปลี่ยนหน้าจอแล้วปล่อย token ใช้งานต่อใน memory Password reset ส่ง email และพาผู้ใช้กลับผ่าน redirect ที่อนุญาต จากนั้นจึงตั้งรหัสใหม่','Access token ที่ออกแล้วอาจยังใช้ได้ถึงเวลาหมดอายุขึ้นกับวิธีตรวจและการตั้งค่า จึงไม่ควรอธิบายว่า Logout ทำให้ JWT ทุกฉบับใช้ไม่ได้ทันที งานที่ต้องตัดสิทธิ์ทันทีต้องออกแบบการตรวจสถานะเพิ่ม')],
example:ex('เริ่ม Guest · Supabase C# API',`// หลังสร้างและ initialize Supabase client ตามแพ็กเกจที่ใช้\nvar session = await supabase.Auth.SignInAnonymously();\nif (session == null)\n    throw new System.Exception("ไม่ได้รับ session");\n// session.User.Id คือรหัสที่จะผูกข้อมูลเกม\n// ไม่แสดงหรือ log access/refresh token ใน production`,['ตัวอย่างนี้ใช้ client supabase ที่ initialize แล้ว ไม่ใช่สคริปต์เดี่ยว','C# client เป็นแพ็กเกจชุมชน ต้องตรวจ compatibility กับ Unity/IL2CPP ของคุณ','Browser lab จำลองผล Auth ไม่สมัครบัญชีจริง']),cases:['ร้านค้า: Guest cart ผูก user ID ก่อนเปลี่ยนเป็นบัญชีถาวร','เว็บเรียน: Login ระบุผู้เรียน แต่สิทธิ์เข้าคอร์สต้องตรวจ enrollment เพิ่ม'],pitfall:'Anonymous user ไม่ใช่ role anon และ user ID ที่ Client ส่งเองอาจเป็นของคนอื่นได้',
exercises:[mc('Guest ที่ Login สำเร็จแล้วใช้ role ใดกับ Data API?',['anon','authenticated','service_role'],1,'Anonymous sign-in สร้าง session จริง จึงใช้ authenticated ความเป็น Guest อยู่ใน claim','แยกชนิดบัญชีกับชนิดคำขอที่ยังไม่ Login'),mc('สมัครแล้ว session เป็น null โดยไม่มี error อาจเกิดจากอะไร?',['ต้องรอยืนยัน email ตามการตั้งค่า','Database เต็มเสมอ','ผู้เล่นได้รับสิทธิ์ admin'],0,'บาง flow คืน user แต่ไม่ให้ session จนยืนยัน email ต้องมีหน้าจอ pending confirmation','อย่าถือว่าการสมัครกับการได้ session เป็นขั้นเดียวกัน'),order('เรียง flow บัญชีที่เปิด email confirmation',['ส่งคำขอสมัคร','แสดงสถานะรอยืนยัน email','ผู้ใช้ยืนยันจาก email','Login และรับ session','โหลดข้อมูลเกม'],'รอให้มี session จริงก่อนอ่านข้อมูลส่วนตัว ไม่ใช้ email เป็นหลักฐานแทน token','การเข้าถึงข้อมูลต้องตามหลังการได้ session')],refs:['anonymous','csharp','sessions']
},
{
id:9,part:2,title:'Auth II: Session, Refresh และผูกบัญชี',duration:70,lab:'session',
lead:'Login ทำงานครั้งเดียวไม่พอ เกมต้องเปิดใหม่ได้ อยู่ในเกมจน token หมดอายุได้ และเปลี่ยน Guest เป็นบัญชีโดยไม่ทำความคืบหน้าหาย',
goals:['อธิบาย access token กับ refresh token','วางการ refresh แบบมีผู้ทำหนึ่งตัว','รักษา user ID เดิมเมื่อผูกบัญชีและจัดการกรณีชนบัญชี'],
sections:[sec('1. Session ประกอบด้วยอะไร','Access token เป็น JWT อายุสั้น ใช้ยืนยันคำขอ Refresh token ใช้ขอคู่ token ใหม่เมื่อจะหมดอายุ JWT มี payload ที่อ่านได้ เช่น sub เป็นรหัสผู้เล่น แต่การ decode ไม่ได้ตรวจลายเซ็น Server ต้องตรวจความถูกต้องและ expiry','Publishable key ไม่ใช่ session และไม่ควรเก็บ password เพื่อ Login อัตโนมัติ เก็บ session ด้วยระบบ secure storage ของแพลตฟอร์มเมื่อทำแอปจริง PlayerPrefs เป็นพื้นที่ธรรมดาจึงไม่เหมาะกับ token ที่ต้องป้องกันการขโมย'),sec('2. Restore ก่อนสร้าง Guest ใหม่','เมื่อเปิดเกมให้ลองโหลด session เดิม ตรวจว่าใช้ต่อได้หรือ refresh ได้ก่อน ถ้ามี session ที่ยังถูกต้อง ให้โหลด profile ของ user ID เดิม การเรียก SignInAnonymously ทุกครั้งสร้างบัญชีใหม่และทำให้ผู้เล่นดูเหมือนเซฟหาย','ถ้า refresh ถูกเพิกถอน ให้ล้าง session และพาเข้าสู่การกู้บัญชีหรือ Login ถ้าเป็นแค่เครือข่ายล้มเหลว อย่ารีบแทน session เดิมด้วย Guest ใหม่ เก็บสถานะ reconnect ให้ผู้เล่นลองต่อได้'),sec('3. Refresh ต้องประสานกัน','ถ้าหน้ากระเป๋า บ้าน และเควสต์เจอ token ใกล้หมดพร้อมกัน อย่าให้ทั้งสามจุด refresh อิสระ ให้รอ task หรือ mutex เดียวแล้วใช้ token คู่ใหม่ร่วมกัน Refresh token มี rotation และกฎ reuse ของผู้ให้บริการ ห้ามออกแบบบนสมมติฐานว่า token เก่าใช้ซ้ำได้ไม่จำกัด','หลัง refresh สำเร็จต้องบันทึกคู่ใหม่ด้วย ไม่อัปเดตเพียง access token ใน memory Retry auth ได้แบบจำกัดครั้ง ถ้าผิดซ้ำให้หยุดวงวนและแสดงสถานะที่ผู้ใช้แก้ได้'),sec('4. ผูก Guest กับบัญชีถาวร','เริ่มจาก Guest user A ที่มีบ้านแล้ว เพิ่ม identity ให้ A แทนสมัคร user B ใหม่ การผูก email ต้องทำตามขั้น verify และการตั้งค่าที่ Supabase กำหนด จึงจะรักษา user ID เดิมได้','ถ้า email นั้นมีบัญชี B อยู่แล้ว นี่คือ account merge ต้อง Login ยืนยันเจ้าของทั้งฝั่งที่เกี่ยวข้องและใช้กฎรวมข้อมูลบน Server ห้ามให้ Client ส่ง user_id เพื่อย้ายของเอง และต้องตัดสินชัดว่าจะรวม inventory และเลือกบ้านใด')],
example:ex('แนวคิด single refresh · C# pseudocode',`// โครงร่าง: Auth adapter และ SecureStore เป็นส่วนที่คุณต้องสร้าง\nawait refreshGate.WaitAsync();\ntry {\n    if (SessionNeedsRefresh()) {\n        session = await auth.RefreshAsync(session.RefreshToken);\n        await secureStore.SaveAsync(session);\n    }\n} finally { refreshGate.Release(); }\n// ตรวจใหม่หลังได้ gate เพราะคำขอก่อนหน้าอาจ refresh ไปแล้ว`,['refreshGate เป็น SemaphoreSlim ที่แชร์ใน Auth service','Adapter ผูกกับ API ของ SDK รุ่นที่ติดตั้งจริง','ไม่ log token และไม่วาง secret key ใน Client']),cases:['แอปธนาคารหรือสมาชิก: เมื่อเปิดแอปต้องคืน session พร้อมมาตรการตามระดับความเสี่ยง','ระบบตะกร้า: ย้าย Guest cart เข้า identity เดิม หรือ merge กับบัญชีเก่าตามกฎธุรกิจ'],pitfall:'decode JWT สำเร็จไม่ได้แปลว่าลายเซ็นถูกต้อง และเก็บ access token อย่างเดียวไม่พอคืน session ระยะยาว',
exercises:[mc('Access token หมด แต่ refresh token ยังใช้ได้ ควรทำอะไร?',['สร้าง Guest ใหม่ทันที','refresh แล้วบันทึกคู่ใหม่','ใช้ publishable key ปลอมเป็นผู้เล่น'],1,'refresh รักษาตัวตนเดิม การสร้าง Guest ใหม่ทำให้ข้อมูลเดิมไม่ใช่ของบัญชีที่กำลังใช้','ต้องรักษา user ID เดิม'),mc('Guest A ต้องการผูก email ใหม่โดยรักษาบ้าน ควรทำอย่างไร?',['สมัคร B แล้วเปลี่ยน FK จาก Client','เพิ่มและยืนยัน identity บน user A','เปลี่ยน username เป็น email'],1,'identity เป็นวิธี Login ส่วน user ID เป็นเจ้าของข้อมูล การเปลี่ยน username ไม่สร้างวิธีพิสูจน์ตัวตน','รักษาเจ้าของเดิม เพิ่มวิธีเข้าใช้'),order('เรียงการ refresh เมื่อหลายระบบเรียกพร้อมกัน',['รอ refresh gate ที่แชร์กัน','ตรวจ expiry อีกครั้ง','ขอคู่ token ใหม่ถ้ายังจำเป็น','บันทึก session ใหม่','ปล่อย gate ให้คำขออื่นใช้ผลเดียวกัน'],'ตรวจใหม่หลังได้ gate ช่วยหลีกเลี่ยง refresh ซ้ำเมื่อมีคนทำไปแล้ว','การตัดสินใจ refresh อยู่ภายใน gate')],refs:['sessions','linking','anonymous']
},
{
id:10,part:2,title:'Profile, Grants และ RLS',duration:70,lab:'rls',
lead:'คุณ Login เป็น A แต่ถ้าเปลี่ยน URL ให้ขอโปรไฟล์ B แล้วอ่านได้ นั่นคือปัญหาสิทธิ์ RLS ช่วยกรองตามผู้เรียกโดยให้ฐานข้อมูลบังคับเอง',
goals:['แยก table grants กับ row policies','ให้ผู้เล่นอ่านเฉพาะข้อมูลของตน','สร้าง profile จาก Auth โดยไม่ให้ Client ตั้ง owner ตามใจ'],
sections:[sec('1. Grants เปิดชนิดงาน RLS เลือกแถว','GRANT SELECT อนุญาตให้ role อ่านตาราง RLS policy กำหนดว่าแถวใดอ่านได้ ต้องผ่านทั้งสองด่าน เปิด RLS แต่ไม่มี policy จะไม่เห็นแถวผ่าน Client ปกติ และมี policy แต่ไม่มี grant ก็ยังถูกปฏิเสธ','SELECT ที่ policy ไม่ match มักได้ array ว่าง การไม่มี grant มักได้ permission error ใช้ความต่างนี้ตรวจปัญหา SQL Editor ที่ใช้สิทธิ์สูงอาจเห็นทุกแถวจึงไม่ใช่การทดสอบผู้เล่นจริง'),sec('2. auth.uid() คือผู้เรียกจากหลักฐานที่ตรวจแล้ว','Policy ใช้ user_id=(select auth.uid()) ไม่ใช่ email หรือ owner ที่มาจาก body รหัสนี้มาจาก context ของ request ที่ Auth ยืนยัน หากยังไม่ Login auth.uid() เป็น NULL','USING ตรวจแถวที่เข้าถึงหรือแก้ได้ WITH CHECK ตรวจแถวใหม่หลัง insert/update สำหรับ update ต้องคิดทั้งสองส่วน มิฉะนั้นอาจย้าย owner หรือเปลี่ยนข้อมูลข้ามผู้เล่นได้'),sec('3. แถวของฉันไม่ได้แปลว่าตั้งเงินเองได้','RLS ที่ยอมให้เจ้าของ UPDATE ทุกคอลัมน์ยังเปิดให้เพิ่มจำนวนไอเทมของตัวเองได้ สำหรับ inventory และ shelter ให้ Client อ่านอย่างเดียว แล้วแก้ผ่าน function ที่ตรวจ action หาก username แก้เองได้ ให้ grant เฉพาะคอลัมน์ username','Function แบบ SECURITY DEFINER ใช้สิทธิ์เจ้าของ ต้องจำกัด EXECUTE ตรวจ auth.uid() ตั้ง search_path และอ้างชื่อ schema ให้ครบ ตัวอย่างหลักสูตรเก็บฟังก์ชันสิทธิ์สูงใน private แล้วเปิด wrapper ที่เป็น SECURITY INVOKER'),sec('4. สร้าง Profile อย่างควบคุม','Auth trigger หลัง insert auth.users สร้าง profile ให้ user ID ใหม่ได้โดยไม่ให้ Client กำหนด owner ฟังก์ชัน trigger ควรเล็กและเชื่อถือได้ เพราะถ้ามัน error อาจทำให้สมัครบัญชีไม่สำเร็จ ผู้ใช้เก่าต้องทำ backfill อย่างตั้งใจ','โค้ด profile read ด้านล่างต่อจากบท 7 เพื่อ bootstrap ผู้ใช้ใหม่ เราเพิ่ม private trigger function: INSERT profiles(user_id) VALUES(new.id); RETURN new; ใช้ SECURITY DEFINER SET search_path=\'\' และ trigger AFTER INSERT ON auth.users การเขียน body เต็มอยู่ในตัวอย่างขยายของบทนี้')],
example:ex('สิทธิ์อ่านและชื่อที่แก้ได้ · PostgreSQL',`grant select on public.profiles to authenticated;\ncreate policy "read own profile" on public.profiles\nfor select to authenticated\nusing (user_id = (select auth.uid()));\n\ngrant update(username) on public.profiles to authenticated;\ncreate policy "edit own name" on public.profiles\nfor update to authenticated\nusing (user_id = (select auth.uid()))\nwith check (user_id = (select auth.uid()));`,['นโยบายแถวและสิทธิ์คอลัมน์ทำงานร่วมกัน','user_id และ created_at ไม่ถูกเปิดให้ Client update','ต้อง revoke สิทธิ์ update ระดับตารางเดิมก่อน grant เฉพาะคอลัมน์']),
extraCode:ex('สร้างโปรไฟล์เมื่อมีผู้ใช้ใหม่ · PostgreSQL',`create schema if not exists private;\ncreate or replace function private.make_profile()\nreturns trigger language plpgsql security definer\nset search_path = '' as $$\nbegin\n  insert into public.profiles(user_id) values (new.id);\n  return new;\nend; $$;\nrevoke all on function private.make_profile() from public, anon, authenticated;\ncreate trigger on_new_auth_user\nafter insert on auth.users\nfor each row execute function private.make_profile();`,['ใช้กับผู้ใช้ที่สร้างหลังเพิ่ม trigger; ผู้ใช้เดิมต้อง backfill','ฟังก์ชันไม่มีพารามิเตอร์ owner จากผู้เล่น','รัน migration นี้ด้วยสิทธิ์ผู้ดูแลในโปรเจกต์พัฒนา']),cases:['แอปโน้ต: ผู้ใช้เห็นเฉพาะ note ของตัวเอง','SaaS หลายทีม: policy ต้องตรวจสมาชิก team ไม่ใช่แค่ Login ผ่าน'],pitfall:'ทดสอบด้วย secret key หรือ SQL Editor อาจ bypass RLS ให้ทดสอบด้วย JWT ของผู้เล่น A/B และคำขอไม่มี session',
exercises:[mc('ให้เจ้าของ UPDATE inventory ทุกคอลัมน์ ปลอดการเพิ่มของเองหรือไม่?',['ปลอดภัยเพราะแก้ได้เฉพาะตนเอง','ยังเพิ่ม quantity ของตนได้','RLS จะตรวจสูตรคราฟต์เอง'],1,'RLS บอกแถวที่เข้าถึงได้ ไม่ได้รู้ว่าหาไอเทมมาอย่างไร ต้อง revoke direct writes และใช้กฎ action','ownership ไม่ใช่หลักฐานความถูกต้องของเศรษฐกิจ'),mc('มี SELECT grant และ RLS เปิด แต่ไม่มี SELECT policy ผู้เล่นปกติเห็นอะไร?',['ทุกแถว','ไม่มีแถวที่ policy อนุญาต','ทุกแถวของ Guest เท่านั้น'],1,'เมื่อเปิด RLS ต้องมี policy ที่ยอมให้ role/request นั้นเห็นแถว','default ของ RLS คือไม่อนุญาต'),order('เรียงวิธีตรวจการอ่านของ A',['Login A และได้ access token','ส่ง publishable key กับ token ของ A','ตรวจ SELECT grant ของ authenticated','ประเมิน policy จาก auth.uid()','คืนเฉพาะแถวที่อนุญาต'],'อย่าพึ่ง owner ที่ส่งจาก Client การประเมินจริงเกิดบน context ที่ Server ตรวจแล้ว','มีสองด่านคือประเภทงานและแถวที่เห็น')],refs:['rls','keys','functions']
},
{
id:11,part:2,title:'Unity เชื่อมข้อมูลจริงและรับมือ Error',duration:65,lab:'response',
lead:'Backend ที่ถูกต้องยังทำให้ผู้เล่นสับสนได้ ถ้า UI ค้างที่ Loading หรือแสดงบ้านใหม่ก่อนคำขอถูกปฏิเสธ เราจะเชื่อมข้อมูลโดยคิดเรื่องสถานะและผลลัพธ์ด้วย',
goals:['อ่านข้อมูลผ่าน UnityWebRequest','ใช้ DTO ให้ตรง JSON และแยก array response','วางสถานะ loading, success, empty และ failure'],
sections:[sec('1. เลือก SDK หรือ REST','Supabase C# SDK ช่วยจัด Auth, session และ query แต่ต้องตรวจรุ่นแพ็กเกจ dependency และการทำงานกับ Unity/IL2CPP REST ทำให้เห็น HTTP ชัดและใช้ UnityWebRequest ได้ แต่คุณต้องจัด session และ error เอง','ตัวอย่างนี้ใช้ REST อ่าน profiles ส่วน Auth adapter เป็นบริการที่เราแยกไว้แล้ว เพื่อไม่ให้สคริปต์ UI ดูแล refresh และความลับกระจายไปทุกหน้าจอ'),sec('2. DTO ให้ตรงรูปร่าง JSON','DTO เป็นคลาสที่ใช้รับข้อมูล เช่น public string username ชื่อต้องตรงกับ field JSON ของ serializer ที่เลือก Supabase table select คืน array JsonUtility ของ Unity รับ object เป็นหลัก จึงห่อ array ด้วย {"rows": ...} แล้ว deserialize เป็น wrapper','ห้ามต่อ JSON body จาก input ผู้ใช้แบบตรง ๆ แต่การห่อ array response ของ Server เพื่อ JsonUtility มีรูปแบบคงที่ จัด nullable timestamp และ bigint ให้สัมพันธ์กับชนิด C# หากซับซ้อนใช้ serializer ที่รองรับอย่างเหมาะสม'),sec('3. Request lifecycle','ตั้ง timeout แสดง loading และปิด action ที่ส่งอยู่จนทราบผล เพื่อ UX เมื่อจบ request ต้องคืน UI ทุกเส้นทาง แยก network/protocol failure จาก array ว่าง และ error ทางธุรกิจ ตัวอย่างไม่ log token หรือ response ที่มีข้อมูลส่วนตัว','หากหน้าจอปิดก่อน request จบ ต้องไม่ update UI ที่ถูกทำลาย อาจใช้ cancellation หรือเช็ก lifetime เมื่อใช้ async การอ่าน GET อาจ retry แบบจำกัดด้วย backoff แต่ POST ที่เปลี่ยนข้อมูลต้องมี request ID'),sec('4. ความจริงอยู่ที่ response','เมื่อ Server ส่ง inventory ใหม่หรือ revision ใหม่ ให้ใช้ผลนั้นเป็นหลัก ถ้าเล่น animation ล่วงหน้าและ Server ปฏิเสธ ต้อง rollback การแสดงผลพร้อมข้อความเข้าใจง่าย อย่าเงียบแล้วปล่อยเลขไม่ตรง','สร้าง BackendService แยกจาก MonoBehaviour UI ทำให้ใช้กับเกมอื่นหรือแอปอื่นได้ และทดสอบ error path โดยจำลอง API response ก่อนต่อ production')],
example:ex('อ่านชื่อจาก REST · ส่วนหนึ่งของ MonoBehaviour',`[System.Serializable] public class ProfileDto { public string username; }\n[System.Serializable] public class ProfileRows { public ProfileDto[] rows; }\n\nIEnumerator LoadProfile(string url, string key, string token) {\n  using (var req = UnityEngine.Networking.UnityWebRequest.Get(\n      url + "/rest/v1/profiles?select=username")) {\n    req.SetRequestHeader("apikey", key);\n    req.SetRequestHeader("Authorization", "Bearer " + token);\n    req.timeout = 15;\n    yield return req.SendWebRequest();\n    if (req.result != UnityEngine.Networking.UnityWebRequest.Result.Success) {\n      UnityEngine.Debug.Log("โหลดไม่สำเร็จ HTTP " + req.responseCode);\n      yield break;\n    }\n    var data = UnityEngine.JsonUtility.FromJson<ProfileRows>(\n      "{\\"rows\\":" + req.downloadHandler.text + "}");\n    if (data.rows == null || data.rows.Length == 0) yield break;\n    UnityEngine.Debug.Log("ชื่อ: " + data.rows[0].username);\n  }\n}`,['เพิ่ม using System.Collections และเรียก StartCoroutine จาก MonoBehaviour','key ต้องเป็น publishable key และ token ต้องมาจาก session','นำ Debug.Log ไปแทนด้วย UI พร้อม empty/error/loading ในงานจริง']),cases:['แอปรายการงาน: โหลด task และแสดงสถานะว่างต่างจากเน็ตล้มเหลว','เครื่องมือภายใน: API service เดียวแชร์ DTO ให้หลายหน้าจอ'],pitfall:'อย่า log Authorization header และอย่าถือว่า array ว่างเป็น exception ของ serializer',
exercises:[mc('Supabase คืน [] แต่ HTTP สำเร็จ ควรแสดงอย่างไร?',['เกมล่มทันที','สถานะไม่มีข้อมูลหรืออธิบายสิทธิ์ตาม context','แสดงข้อมูลเก่าราวกับเป็นข้อมูลล่าสุดเสมอ'],1,'empty เป็นสถานะที่ต้องจัดการ อาจไม่มีแถวหรือ RLS กรอง ไม่ใช่ network error','แยกการโหลดได้จากการมีข้อมูล'),mc('Secret key ฝังในสคริปต์ Unity แล้วทำ obfuscation ใช้ได้หรือไม่?',['ได้เพราะ C# ถูก compile','ไม่ควรแจก secret ใน Client','ได้ถ้าไม่แสดงใน Inspector'],1,'ผู้เล่นควบคุมเครื่องที่รันเกมและอ่าน build ได้ ใช้ publishable key กับ session และสิทธิ์ที่เหมาะ','คิดว่าใครได้รับไฟล์ executable'),order('เรียงการแสดงข้อมูลจาก request',['ตั้งสถานะ loading','ส่ง HTTP พร้อม session','ตรวจผล network และ HTTP','deserialize และจัดการ empty','แสดงผลและจบ loading'],'ทุกเส้นทางต้องจบสถานะ loading ส่วน error ไม่ควรใช้ DTO success โดยไม่ตรวจ','ตรวจความสำเร็จก่อนอ่านข้อมูลของผลสำเร็จ')],refs:['unity','keys','csharp']
},
{
id:12,part:3,title:'Server Time และการปลูกพืช',duration:60,lab:'time',
lead:'เวลาเครื่องใช้แสดงผลได้ แต่ผู้เล่นเปลี่ยนมันได้ ถ้าแค่เลื่อนนาฬิกาแล้วเก็บผักได้ฟรี กฎเวลาของเกมก็ถูกตัดสินบนฝั่งที่ผู้เล่นควบคุม',
goals:['เก็บ timestamp แทนบันทึกตัวนับทุกวินาที','ให้ Server ตรวจ ready_at ก่อนแจกผลผลิต','แยกเวลาที่ UI ประมาณจากเวลาที่ตัดสินผลจริง'],
sections:[sec('1. เก็บเวลาพร้อมเสร็จ','เมื่อปลูก Server บันทึก started_at และ ready_at=เวลา Server+ระยะปลูก ไม่ต้อง UPDATE ตารางทุกวินาที วันต่อมาอ่าน ready_at แล้วคำนวณเวลาที่เหลือได้ การปิดเกมไม่ทำให้เวลาในกฎหยุด','ใช้ timestamptz แทน string วันที่ที่ไม่มี timezone เก็บจุดเวลาจริงแล้วค่อยแปลงเพื่อแสดง ภาษาและรูปแบบวันที่เป็นเรื่องของ UI ไม่ควรนำ string ที่ผู้เล่นส่งมาเป็นเวลาจริง'),sec('2. now() มีความหมาย','PostgreSQL now() เป็นเวลาต้น transaction และคงที่ตลอด transaction นั้น เหมาะกับการใช้ instant เดียวอ้างอิงหลายขั้น clock_timestamp() เป็นเวลาปัจจุบันขณะที่เรียก หากต้องการเวลาที่ไหลระหว่าง transaction ใช้ให้ตรงงาน','เกมไม่ควรเปิด transaction ค้างรอผักโต บันทึก ready_at แล้วจบ transaction ตอนปลูก เมื่อเก็บเกี่ยวจึงเปิดอีกคำขอและตรวจเวลาในตอนนั้น'),sec('3. Client countdown เป็นการประมาณ','Server ส่ง server_now และ ready_at กลับมา Client จับ elapsed ด้วยนาฬิกา monotonic เช่น Time.realtimeSinceStartup แล้วแสดง remaining=max(0,ready_at-server_now-elapsed) วิธีนี้ไม่กระโดดตามการแก้เวลาปฏิทินของเครื่องระหว่าง session','หลังพักแอปหรือ reconnect ให้ sync ใหม่ latency ทำให้ UI คลาดเล็กน้อยได้ แต่สุดท้าย RPC เก็บเกี่ยวต้องตรวจเวลา Server อีกครั้ง แม้ UI แสดง 0 ก็อาจถูกขอให้รออีกนิด'),sec('4. เวลาอย่างเดียวไม่กันรางวัลซ้ำ','Harvest ต้องตรวจทั้ง owner, ready_at และสถานะ harvested แล้วแจกผลผลิตพร้อมเปลี่ยนสถานะใน transaction เดียว สองคำขอพร้อมกันต้องไม่รับผลผลิตสองครั้ง','Server time กันการโกงเวลาจากเครื่อง แต่ไม่พิสูจน์ว่าผู้เล่นทำทุก action ในเกมอย่างถูกต้อง ถ้า Client ส่ง harvest ได้ไม่จำกัดโดยไม่ตรวจแปลงและผลเดิม ระบบก็ยังถูกใช้ผิดกฎได้')],
example:ex('รูปแบบข้อมูลเวลา · PostgreSQL / response',`-- ตัวอย่างตอนปลูกใน RPC ที่ตรวจสิทธิ์แล้ว\nready_at := now() + interval '5 minutes';\n\n-- ตอนเก็บเกี่ยวในคำขอใหม่\nif now() < v_ready_at then\n  raise exception 'NOT_READY';\nend if;\n\n// ส่ง server_now และ ready_at เป็น ISO 8601 ที่มี offset`,['v_ready_at ต้องอ่านจากแปลงของผู้เรียก ไม่รับจาก Client','ต้องล็อกและตรวจสถานะก่อนแจกของ','โค้ดเป็น fragment ภายใน function ไม่ใช่ SQL เดี่ยว']),cases:['คูปอง: Server ตรวจวันหมดอายุแม้เครื่องลูกค้าตั้งเวลาเก่า','จองสินค้า: เก็บ expires_at แล้วตรวจตอนชำระ แทน worker ลดตัวนับทุกวินาที'],pitfall:'นับวินาทีใน Unity อย่างเดียวไม่รองรับปิดเกม และเก็บเกี่ยวแบบไม่ทำ atomic state transition อาจแจกซ้ำ',
exercises:[num('Server เริ่มปลูกที่วินาที 100 ใช้เวลา 300 วินาที ready_at เป็นวินาทีใด?',400,'บันทึกเวลาเสร็จด้วย 100+300 เมื่อ Client เปลี่ยนนาฬิกา ready_at บน Server ไม่เปลี่ยน','บวกเวลาปัจจุบันบน Server กับระยะปลูก'),num('ready_at=400 และ Server ตอนนี้=250 เหลือกี่วินาที?',150,'remaining=400-250 เวลาของเครื่องอาจต่างกันแต่ไม่ใช้ตัดสินผล','ลบเวลา Server จากเวลาเสร็จ'),mc('UI แสดงนับถอยหลังถึง 0 แล้ว ควรแจกผลผลิตตรงไหน?',['Unity เพิ่ม inventory ทันที','RPC ตรวจเวลาและสถานะแล้วแจกใน transaction','ให้ Client ส่ง ready_at ใหม่'],1,'UI เป็นการประมาณ Server ต้องตรวจข้อมูลที่ตนเก็บและป้องกันรับซ้ำ','เวลาที่เห็นบนหน้าจอกับหลักฐานรับรางวัลเป็นคนละชั้น')],refs:['datetime','locks']
},
{
id:13,part:3,title:'Inventory, Catalog และของที่มีตัวตนเฉพาะ',duration:60,lab:'sql',
lead:'ไม้ 10 ชิ้นและดาบเล่มหนึ่งไม่จำเป็นต้องใช้โครงสร้างเดียวกัน บทนี้ทำกระเป๋าให้เหมาะกับทั้งการนับ การตรวจ และการขยายชนิดไอเทม',
goals:['แยก catalog, stack และ instance','อ่านกระเป๋าพร้อมข้อมูลชื่อ','กำหนดสิทธิ์อ่านแต่ไม่เปิด direct writes'],
sections:[sec('1. Catalog เป็นนิยาม Inventory เป็นความเป็นเจ้าของ','item_catalog เก็บ id,name,max_stack หรือชนิด item ส่วน user_inventory เก็บ user_id,item_id,quantity เกมอาจ cache catalog เพราะเปลี่ยนไม่บ่อย แต่จำนวนที่ถือเป็นข้อมูลผู้เล่นที่ต้อง sync หลัง action','อย่าใช้ชื่อภาษาไทยเป็น item_id เพราะจะเปลี่ยนเมื่อแปลภาษา ใช้รหัสคงที่เช่น wood ส่วนชื่อที่แสดงมาจาก localization หรือ catalog ตามแบบเกม'),sec('2. Stack กับ instance','วัตถุดิบที่เหมือนกันทุกชิ้นใช้ quantity ได้ง่าย หากกระเป๋ามีช่องและแต่ละช่องจำกัด stack ต้องมี slot_id เพิ่ม และตรวจความจุ ตอนนี้เราใช้กระเป๋าวัตถุดิบแบบจำนวนรวมเพื่อเรียนพื้นฐาน','เฟอร์นิเจอร์ที่วางได้แต่ละชิ้นอาจต้องมี furniture_instance.id เพื่อห้ามวางชิ้นเดียวสองครั้ง แม้ catalog บอกว่าเป็น chair แบบเดียวกัน ต่อจากบทนี้บท 17 จะใช้รหัส instance กับ Layout'),sec('3. เพิ่มของด้วย action ที่มีที่มา','อย่าเปิด RPC add_item(item_id,amount) ให้ผู้เล่นเรียกตามใจ ถึงใช้ auth.uid() ก็ยังแจกของให้ตัวเองไม่จำกัด ให้มี harvest_plot, craft_chair หรือ claim_quest ที่ตรวจเหตุผลและคำนวณจำนวนเอง','สำหรับการทดลองจริงเติมของด้วย SQL Editor ของผู้ดูแลใน development เท่านั้น ระบบ production ควรมี audit หรือ transaction record ตามความต้องการ และไม่เปิดเส้นทาง debug ให้ Client'),sec('4. Index และการอ่าน','Composite PK(user_id,item_id) เป็น index ที่ช่วยค้นหาตาม user_id และตามคู่ key ได้ แต่ไม่ได้เหมาะกับ query ที่กรอง item_id อย่างเดียวทุกกรณี ให้เพิ่ม index เมื่อรูปแบบ query และข้อมูลบอกว่าจำเป็น','ส่งเฉพาะคอลัมน์ที่ UI ใช้ และอัปเดตกระเป๋าจาก response ของ action หรืออ่าน snapshot หลังเปลี่ยน ไม่ต้อง poll จำนวนทุกวินาที ถ้ามีสองเครื่อง revision ช่วยบอกว่าข้อมูลใหม่กว่า')],
example:ex('catalog และสิทธิ์อ่าน · PostgreSQL',`create table public.item_catalog (\n  id text primary key, name text not null\n);\ninsert into public.item_catalog values\n  ('wood','Wood'), ('stone','Stone'), ('chair','Chair');\nalter table public.item_catalog enable row level security;\nrevoke all on public.item_catalog from anon, authenticated;\ngrant select on public.item_catalog to authenticated;\ncreate policy "read catalog" on public.item_catalog\nfor select to authenticated using (true);\n-- user_inventory ใช้ schema บท 3 เปิด SELECT เฉพาะ owner แบบบท 10`,['catalog เป็นข้อมูลกลาง ผู้ใช้ Login อ่านได้','อย่า grant insert/update/delete แก่ authenticated','inventory ต้องมี RLS และ SELECT policy ของตนเอง']),cases:['คลังสินค้า: SKU เป็น catalog ปริมาณแยกต่อคลัง ส่วนเครื่องมี serial เป็น instance','ห้องสมุด: ชื่อหนังสือเป็น catalog แต่เล่มที่ยืมมี barcode ของตัวเอง'],pitfall:'catalog ที่ Client cache ไม่ควรเป็นแหล่งราคาหรือสูตรที่ Server เชื่อถือจากคำขอ',
exercises:[sq('อ่าน item_id และ quantity ของ B เรียง item_id','SELECT ... FROM inventory;','SELECT item_id,quantity FROM inventory WHERE user_id=\'B\' ORDER BY item_id;',{kind:'result',values:[['seed',5],['wood',3]]},'อ่านกระเป๋าของ B ใน sandbox เพื่อฝึก query ในระบบจริง RLS จำกัดเจ้าของด้วย session','ใช้ WHERE user_id=\'B\''),mc('ไอเทมใดเหมาะกับ instance_id มากที่สุด?',['ไม้ที่เหมือนกันทุกชิ้น','ดาบที่มี durability และ enchant ต่างกัน','เหรียญชนิดเดียวกัน'],1,'ความแตกต่างของแต่ละเล่มเป็นข้อมูลประจำชิ้น quantity อย่างเดียวเก็บไม่ได้','ต้องรู้ว่าเป็นเล่มไหนหรือแค่กี่ชิ้น'),mc('RPC add_item ที่ผู้เล่นเลือก amount เองปลอดภัยเพราะใช้ auth.uid() หรือไม่?',['ปลอดภัย','ไม่ปลอดภัย ต้องตรวจที่มาของรางวัล','ปลอดภัยถ้าจำนวนไม่ติดลบ'],1,'การพิสูจน์เจ้าของไม่ได้พิสูจน์สิทธิ์รับของ ต้องมี action ที่ตรวจเหตุผล','ใครคำนวณจำนวนรางวัล')],refs:['rls','constraints']
},
{
id:14,part:3,title:'RPC คราฟต์: ตรวจ หัก และเพิ่มในคำขอเดียว',duration:80,lab:'craft',
lead:'เราจะรวมสิ่งที่เรียนมาเป็น action จริง: ตรวจผู้เรียก ล็อก อ่านทรัพยากร หักไม้ 6 และเพิ่มเก้าอี้ 1 ถ้าขั้นใดผิดต้องไม่เกิดผลครึ่งเดียว',
goals:['อ่าน PL/pgSQL function และคืน JSON','จำกัด function privileges พร้อมตรวจ auth.uid()','รวม lock และ transaction ให้กฎคราฟต์ทำงานสอดคล้องกัน'],
sections:[sec('1. Function เป็นสัญญา API','Client เรียก craft_chair โดยไม่ส่ง user_id,ราคา หรือผลผลิต Server ใช้ auth.uid() แล้วสูตรที่ฝังหรือเก็บในตารางกลาง หากใช้ recipe_id ให้ตรวจ active และเงื่อนไข unlock รวมถึง version ที่ใช้','Functions ใช้ SQL หรือ PL/pgSQL ได้ PL/pgSQL มีตัวแปร IF และ RAISE EXCEPTION เหมาะกับกฎหลายขั้น หาก exception หลุดออก การเปลี่ยนในคำขอถูก rollback'),sec('2. Invoker และ Definer','SECURITY INVOKER ใช้สิทธิ์ผู้เรียก เหมาะเมื่อผู้เรียกมีสิทธิ์ที่ต้องใช้ SECURITY DEFINER ใช้สิทธิ์เจ้าของ function จึงแก้ตารางที่เราไม่เปิดให้ Client เขียนได้ แต่ต้องตรวจผู้เรียกเองและจำกัด EXECUTE','ตัวอย่างใช้ private.craft_chair เป็น definer และ public.craft_chair เป็น invoker wrapper private ไม่อยู่ใน exposed schemas ให้ authenticated มี USAGE กับ EXECUTE เท่าที่ wrapper ต้องใช้ แต่ไม่มีสิทธิ์เขียน inventory ตรง'),sec('3. ล็อกต่อผู้เล่นก่อนแก้','เราล็อก profiles ของ user ID ก่อนอ่าน inventory ทุก action เศรษฐกิจที่เกี่ยวข้องต้องใช้คิวนี้ร่วมกัน จากนั้น conditional update หัก wood เฉพาะมีพอ ตรวจ FOUND ถ้า false raise NOT_ENOUGH_WOOD','หลังหัก insert chair แล้ว ON CONFLICT เพิ่มจำนวน ถ้าขั้น insert ล้มเหลว การหักไม้ย้อนกลับ นี่ไม่ได้ป้องกัน retry หลังสำเร็จ บท 15 ต้องเพิ่ม request log'),sec('4. Error เป็นส่วนหนึ่งของ API','UNAUTHENTICATED, PROFILE_MISSING และ NOT_ENOUGH_WOOD มีความหมายต่างกัน UI ควรแสดงข้อความตาม action ไม่จำเป็นต้องโชว์ SQL error ดิบให้ผู้เล่น แต่เก็บ diagnostic ที่ปลอดภัยไว้ตรวจ','ตัวอย่างย่อจำกัดสูตรเดียวและไม่มีจำนวน batch เพื่อให้เห็นโครงสร้าง เมื่อขยายต้องตรวจ input, overflow,capacity และ consistency ของสูตร ไม่ให้ Client ขอจำนวนติดลบหรือมหาศาล')],
example:ex('ตัวอย่าง RPC ครบสูตรเดียว · PostgreSQL',`create or replace function private.craft_chair()\nreturns jsonb language plpgsql security definer set search_path='' as $$\ndeclare uid uuid := auth.uid();\nbegin\n  if uid is null then raise exception 'UNAUTHENTICATED'; end if;\n  perform 1 from public.profiles where user_id=uid for update;\n  if not found then raise exception 'PROFILE_MISSING'; end if;\n  update public.user_inventory set quantity=quantity-6\n    where user_id=uid and item_id='wood' and quantity>=6;\n  if not found then raise exception 'NOT_ENOUGH_WOOD'; end if;\n  insert into public.user_inventory(user_id,item_id,quantity)\n    values(uid,'chair',1)\n    on conflict(user_id,item_id) do update\n    set quantity=public.user_inventory.quantity+1;\n  return jsonb_build_object('crafted','chair','amount',1);\nend; $$;\nrevoke all on function private.craft_chair() from public,anon,authenticated;\ngrant usage on schema private to authenticated;\ngrant execute on function private.craft_chair() to authenticated;\n\ncreate or replace function public.craft_chair()\nreturns jsonb language sql security invoker set search_path='' as $$\n  select private.craft_chair();\n$$;\nrevoke all on function public.craft_chair() from public,anon,authenticated;\ngrant execute on function public.craft_chair() to authenticated;`,['ก่อนรันต้องมี profiles, item_catalog และ user_inventory ตามบทก่อน','ต้องมี catalog wood/chair และเติม wood โดยผู้ดูแลใน development','private schema ต้องไม่อยู่ในรายการ exposed schemas','Client POST /rest/v1/rpc/craft_chair body {} พร้อม user JWT','ยังไม่มี idempotency; อย่า retry โดยคิดว่าไม่มีผลซ้ำ']),cases:['แลกแต้มสมาชิก: หักแต้มและสร้างสิทธิ์แลกของในชุดเดียว','สั่งซื้อ: ตรวจ stock และบันทึกออเดอร์ แต่การจ่ายเงินภายนอกต้องออกแบบขั้นเพิ่ม'],pitfall:'ถ้าจับ exception แล้วคืน success ทั้งที่บางขั้นผิด คุณอาจทำให้ rollback ที่คาดไว้ไม่เกิดตามขอบเขตที่ต้องการ',
exercises:[mc('RPC ควรเลือก user_id จากไหน?',['body ที่ผู้เล่นส่ง','auth.uid() จาก request context','ชื่อที่แสดงในเกม'],1,'ผู้เล่นปลอม body ได้ แต่ตัวตนต้องมาจาก token ที่ตรวจแล้ว','อย่าให้ผู้ขอเลือกเจ้าของที่ใช้สิทธิ์สูง'),num('มี wood=19 คราฟต์ chair ครั้งละ 6 สำเร็จ 3 ครั้ง เหลือ wood เท่าไร?',1,'หัก 18 เหลือ 1 ทุกครั้งต้องมีพอ และสำเร็จเป็นชุด','19 - 6×3'),order('เรียงกฎคราฟต์',['ตรวจผู้เรียก','ล็อก profile ของผู้เรียก','ตรวจและหักไม้ที่มีพอ','เพิ่มเก้าอี้','คืนผลหลังชุดบันทึกสำเร็จ'],'สิทธิ์สูงต้องเริ่มที่ตัวตนและความเป็นเจ้าของ แล้วควบคุมข้อมูลที่เขียน','คราฟต์ต้องไม่เพิ่มก่อนรู้ว่าหักสำเร็จ')],refs:['functions','rls','locks']
}
);
chapters.push(
{
id:15,part:3,title:'คำขอซ้ำและ Idempotency: ทำครั้งเดียวแม้ส่งหลายครั้ง',duration:65,lab:'retry',
lead:'คำขอคราฟต์สำเร็จและหักไม้แล้ว แต่ response หายระหว่างทาง Unity timeout แล้วส่งใหม่ จะหักอีกครั้งไหม? Transaction ไม่ได้รู้ว่าสอง request เป็นความตั้งใจเดียวกัน',
goals:['แยกการส่ง request ใหม่กับ retry action เดิม','ออกแบบ request ID และผลที่บันทึกไว้','ไม่ถือว่าปุ่ม disabled ป้องกัน duplicate ได้'],
sections:[sec('1. โลกเครือข่ายไม่มีคำตอบแน่นอนทุกครั้ง','Client อาจรู้ว่าสำเร็จ รู้ว่ากฎปฏิเสธ หรือไม่รู้ผลเพราะ timeout การ retry โดยไม่วางกฎทำให้ action เดิมมีผลซ้ำ Idempotency หมายถึงใช้คำขอเดิมซ้ำแล้วไม่เกิดผลเพิ่มจากครั้งแรก','GET อ่านข้อมูลมัก retry ได้ง่าย แต่ POST แจกของหรือหักของต้องมีตัวระบุ action ไม่ใช่ใช้ช่วงเวลาใกล้กันเป็นหลักฐานว่าเป็น action เดียว'),sec('2. หนึ่งความตั้งใจ หนึ่ง ID','ก่อนส่ง action สร้าง UUID และเก็บจนทราบผล Retry ใช้ ID เดิม ผู้เล่นตั้งใจคราฟต์เก้าอี้อีกตัวค่อยสร้าง ID ใหม่ ถ้าสร้าง UUID ใหม่ทุกครั้งที่กด retry ระบบจะแยกไม่ออกว่าเป็นคำขอใหม่','ตาราง action_receipts มี PK(user_id,request_id) พร้อม action_type, payload_hash และ result การส่ง ID เดิมแต่เปลี่ยน recipe หรือจำนวนต้องถูกปฏิเสธ มิฉะนั้นผลเดิมอาจถูกตีความเป็นคนละงาน'),sec('3. ผลและ receipt ต้องบันทึกพร้อมกัน','เริ่มตรวจ auth แล้วล็อก profile เดียวกับ action เศรษฐกิจ ตรวจ receipt ถ้ามีและ payload ตรง คืน result เดิม ถ้ายังไม่มีทำ action แล้ว insert receipt พร้อมผล ภายใน transaction เดียว หาก rollback จะไม่มีทั้งผลและ receipt','หากแค่เช็ก receipt ก่อนแต่ไม่ล็อกหรือไม่ใช้ uniqueness สองคำขออาจไม่พบพร้อมกันแล้วทำทั้งคู่ ค่า unique เป็นด่านสุดท้ายแต่ต้องวางการ rollback/อ่านผลให้ตรงแบบ'),sec('4. Retry ต้องจำกัดและสังเกตได้','ใช้ backoff เพิ่มเวลารอ เช่น 1,2,4 วินาทีพร้อม jitter และขอบเขตจำนวนครั้ง 429 ควรเคารพแนวทางรอของบริการ อย่า retry ข้อผิดพลาดสูตรไม่พอราวกับเป็นปัญหาเน็ต','Receipt มีขนาดเพิ่มเรื่อย ๆ วางอายุเก็บตามระยะ retry ที่รองรับและกฎเกม ถ้าลบเร็วเกินไป action เก่าที่กลับมาจะถูกมองเป็นใหม่ งานรับรางวัลใช้ unique claim ระยะยาวตาม period เพิ่มด้วย')],
example:ex('receipt และลำดับใน RPC · PostgreSQL fragment',`create table public.action_receipts (\n  user_id uuid references public.profiles(user_id),\n  request_id uuid, action_type text not null,\n  payload_hash text not null, result jsonb not null,\n  created_at timestamptz not null default now(),\n  primary key(user_id,request_id)\n);\n-- ใน private action function หลังล็อก profile:\n-- 1. หา receipt ตาม user_id และ request_id\n-- 2. ถ้ามี ตรวจ type/hash แล้ว RETURN result เดิม\n-- 3. ถ้าไม่มี ทำ action และ INSERT receipt ใน transaction เดียว`,['นี่เป็น schema กับโครงร่าง ไม่ใช่ implementation function เต็ม','Client ไม่ได้สิทธิ์เขียน receipts ตรง','payload hash ต้องมาจากข้อมูล normalized ที่ Server ตรวจแล้ว']),cases:['สั่งอาหาร: retry หลัง timeout ต้องไม่สร้างออเดอร์สองชุด','Webhook: ผู้ให้บริการส่ง event เดิมซ้ำ ใช้ event_id ที่เชื่อถือได้ป้องกันทำผลซ้ำ'],pitfall:'Idempotency ไม่ใช่ห้ามทำ action ซ้ำตลอดชีวิต แต่ห้ามความตั้งใจเดียวมีผลมากกว่าครั้งที่กำหนด',
exercises:[mc('timeout ของ action เดิมควรใช้ request ID ใด?',['ID เดิม','ID ใหม่ทุกครั้ง','ไม่ส่ง ID'],0,'ID เดิมทำให้ Server คืนผลเดิม ส่วน action ใหม่จริงจึงใช้ ID ใหม่','ตัวระบุผูกกับความตั้งใจ ไม่ใช่จำนวนครั้งที่ส่ง'),num('ไม้ 20 คราฟต์ครั้งละ 6 ส่ง action X เดิม 3 ครั้ง ระบบ idempotent เหลือไม้เท่าไร?',14,'ทั้งสาม request คือหนึ่ง action จึงหักครั้งเดียว ถ้าเป็นสาม action ใหม่จะเหลือ 2','นับ action ที่แตกต่าง ไม่ใช่ request'),order('เรียง RPC ที่รับ retry',['ตรวจตัวตนและล็อกผู้เล่น','หา receipt และตรวจ payload','คืนผลเดิมถ้ามี หรือทำ action ถ้ายังไม่มี','บันทึกผลกับ receipt ใน transaction เดียว'],'ขั้น receipt และผลต้องไม่แยกเป็นสอง transaction ที่มีช่องว่าง','ต้องควบคุม concurrency ก่อนตัดสินว่ายังไม่มี receipt')],refs:['locks','functions']
},
{
id:16,part:4,title:'อัปเกรดบ้าน: State Machine และเวลารอ',duration:70,lab:'shelter',
lead:'บ้านไม่ใช่แค่ level=2 มันมีสถานะพร้อมใช้งาน กำลังก่อสร้าง และเสร็จแล้ว ถ้าไม่กำหนด transition ชัด ผู้เล่นอาจเริ่มซ้อนหรือรับเลเวลซ้ำ',
goals:['วาง state transition ของสิ่งปลูกสร้าง','แยก start กับ complete และตรวจเวลาบน Server','ตรวจสถานะพร้อมทรัพยากรใน transaction'],
sections:[sec('1. State machine ทำให้กฎอ่านออก','กำหนด idle → building → idle พร้อม level เพิ่มหนึ่งตอน complete start ทำได้เมื่อ idle complete ทำได้เมื่อ building และ now()>=ready_at ไม่เปิด action ตั้ง level ตรง ๆ','ไม่จำเป็นต้องเก็บสถานะ ready ถ้าอนุมานจาก building และเวลาได้ UI แสดงพร้อมรับเมื่อถึงเวลาได้ แต่ฐานข้อมูลยังเป็น building จน complete สำเร็จ'),sec('2. เริ่มอัปเกรด','start_upgrade ตรวจ owner ล็อก profile อ่าน shelter และราคาเลเวลถัดไป ตรวจเงื่อนไข unlock หักไม้/เงิน บันทึก target_level และ ready_at พร้อม receipt แล้วคืน snapshot ให้ UI','อย่าให้ Client เลือก duration=0 หรือ price=1 ด้วย body ใช้ค่าจาก config ที่ Server เชื่อถือได้ หาก config เปลี่ยนระหว่างก่อสร้าง ให้ ready_at ที่บันทึกตอนเริ่มเป็นสัญญาที่ชัดเจน'),sec('3. จบอัปเกรด','complete ตรวจ state และเวลาในคำขอใหม่ ล็อกตามกฎเดียวกัน เปลี่ยน level=target_level ล้าง target/ready_at และกลับ idle ใน transaction หลังจบคำขอซ้ำต้องไม่เพิ่ม level อีก','กำหนดว่า complete ซ้ำคืน snapshot ปัจจุบันหรือ error ALREADY_COMPLETED แบบไหนก็ได้ถ้า API ชัด แต่ผลถาวรต้องไม่ถูกเพิ่มสองครั้ง ใช้ request receipt เมื่อ Client ต้องการคำตอบเดิม'),sec('4. วาง schema เพื่อขยาย','หนึ่งบ้านต่อผู้เล่นใช้ PK user_id ถ้ามีหลายอาคารใช้ building_id และ owner_id FK ส่วน upgrade_rules เก็บ from_level,cost,duration แยกนิยามจากสภาพบ้าน','เพิ่ม CHECK ที่ผูก state กับข้อมูล เช่น idle ต้องไม่มี target/ready_at และ building ต้องมีทั้งสอง สำหรับหลายเครื่อง revision และ Server response ช่วยทำให้ทุกเครื่องยึด snapshot ล่าสุด')],
example:ex('โครงสร้างบ้าน · PostgreSQL',`create table public.shelters (\n user_id uuid primary key references public.profiles(user_id),\n level integer not null default 1 check(level>=1),\n state text not null default 'idle' check(state in ('idle','building')),\n target_level integer, ready_at timestamptz,\n check(\n   (state='idle' and target_level is null and ready_at is null) or\n   (state='building' and target_level is not null and target_level=level+1 and ready_at is not null)\n )\n);\n-- เปิด RLS + SELECT owner; ไม่เปิด direct UPDATE ให้ Client`,['CHECK มี NOT NULL แยกที่คอลัมน์สำคัญ','state building ต้องมี target_level เพิ่มหนึ่ง','แก้บ้านผ่าน start/complete ที่ตรวจตัวตนและล็อก']),cases:['ระบบอนุมัติเอกสาร: draft → submitted → approved โดยแต่ละ transition มีผู้มีสิทธิ์','ออเดอร์ร้านค้า: paid → packing → shipped ห้ามข้ามโดย request ผู้ซื้อ'],pitfall:'เก็บเพียง level แล้วใช้ Client countdown ทำให้ Server ไม่รู้ว่ามีงานอัปเกรดค้างอยู่',
exercises:[mc('ตอนกดเริ่มอัปเกรดควรเพิ่ม level ทันทีหรือไม่?',['เพิ่มทันทีแล้ว Client รอเอง','เก็บ target/ready_at และเพิ่มเมื่อ complete ผ่านเงื่อนไข','ให้ Client เลือก'],1,'แบบนี้แยกกำลังก่อสร้างจากผลที่เสร็จแล้วและตรวจการรับผลซ้ำได้','state ของบ้านมีความหมายต่อการใช้งาน'),num('เริ่มเวลา Server=900 ระยะ 120 และ complete ตอน 1000 ต้องรออีกกี่วินาที?',20,'ready_at=1020 จึงยังไม่ผ่าน complete ต้องรอ 20 วินาที','900+120-1000'),order('เรียงขั้น start upgrade',['ล็อกและอ่านบ้านที่เป็น idle','อ่านราคา/ระยะจากกฎ Server','ตรวจและหักทรัพยากร','บันทึก building,target_level,ready_at','คืน snapshot และ receipt'],'ถ้าอ่านราคา Client หรือลืมตรวจ state จะเปิดให้เริ่มซ้อนหรืออัปฟรี','ทรัพยากรและสถานะต้อง commit ด้วยกัน')],refs:['constraints','datetime','locks']
},
{
id:17,part:4,title:'Layout เฟอร์นิเจอร์และการเขียนจากสองเครื่อง',duration:65,lab:'layout',
lead:'แท็บเล็ตเปิด Layout รุ่น 4 อยู่ มือถือบันทึกรุ่น 5 แล้ว หากแท็บเล็ตส่ง snapshot เก่ามาทับ บ้านล่าสุดจะหาย เราต้องตรวจเวอร์ชันก่อนรับ snapshot',
goals:['เลือกระหว่าง snapshot JSON กับแถวเฟอร์นิเจอร์','ตรวจ owner, bounds และ instance ซ้ำ','ใช้ revision ตรวจ optimistic concurrency'],
sections:[sec('1. Snapshot หรือแถวแยก','ถ้ามักโหลดทั้งห้องและมีชิ้นไม่มาก เก็บ layout jsonb กับ revision ได้ง่าย ถ้าต้องค้นเฟอร์นิเจอร์แต่ละชิ้นหรือมีห้องใหญ่มาก แถวแยก instance_id,x,y,rotation ทำให้ query และ constraint ชัด','snapshot ยังต้องตรวจรูปแบบ จำนวนชิ้น พื้นที่ และสิทธิ์ใช้ instance ไม่ใช่รับ JSON อะไรก็ได้ เพราะ object ที่ดูถูกบน Client อาจถูกปลอมก่อนส่ง'),sec('2. Validation ของตำแหน่ง','Server ตรวจ instance_id เป็นของผู้เรียกและวางไม่ซ้ำ x/y อยู่ในขอบห้อง rotation อยู่ในค่าที่อนุญาต หากเกมห้าม overlap ต้องตรวจ footprint และการชน ไม่ใช่แค่เช็กตำแหน่งจุดศูนย์กลาง','ตัวทดลองใช้กริด 4×4 และเฟอร์นิเจอร์แต่ละชิ้นกว้างหนึ่งช่องเพื่อสอนหลักการ เกมจริงที่มีขนาดชิ้นใหญ่และหมุนได้ต้องเพิ่ม geometry validation'),sec('3. Optimistic concurrency','Client ส่ง expected_revision=4 Server แก้ได้เมื่อ revision ปัจจุบันยังเท่ากับ 4 แล้วเพิ่มเป็น 5 หากไม่ตรงคืน conflict พร้อมให้โหลด snapshot ล่าสุด คำว่า optimistic หมายถึงหวังว่าจะไม่ชน แต่ตรวจตอนเขียน','conditional UPDATE ... WHERE revision=p_expected รวมการตรวจและเขียนใน statement เดียวได้ ต้องตรวจ affected rows และห้ามแก้ layout โดยเส้นทางที่ไม่เพิ่ม revision'),sec('4. UX เมื่อ conflict','อย่า silently ทับข้อมูลใหม่ ให้แจ้งว่ามีการเปลี่ยนจากอีกเครื่องแล้วเสนอโหลดล่าสุด เก็บแบบร่างของผู้ใช้ไว้เพื่อเลือกใช้หรือ merge ถ้า merge ต้องมีกฎระดับชิ้นและทดสอบมากขึ้น','ใช้ debounce บันทึกเมื่อหยุดจัดหรือกดยืนยัน แทนส่งทุก frame ลด request และหลีกเลี่ยง snapshot แข่งกันใน Client เครื่องเดียว')],
example:ex('ตรวจ revision ตอนเขียน · PostgreSQL fragment',`-- ภายใน RPC หลังตรวจ owner และ validate p_layout แล้ว\nupdate public.shelter_layouts\nset layout=p_layout, revision=revision+1\nwhere user_id=auth.uid() and revision=p_expected_revision\nreturning revision,layout;\n-- ต้องตรวจว่า update ได้หนึ่งแถว\n-- ถ้าได้ 0 อาจไม่มีแถวหรือ revision ไม่ตรง: จัดการตามสัญญา API`,['ต้องมี schema shelter_layouts และสิทธิ์ RPC ที่เหมาะสมก่อน','อย่าเปิด direct update ที่ข้าม validation','เลข revision ไม่ใช่เวลา และไม่ใช่ request ID']),cases:['แก้บทความ: ป้องกัน draft เก่าทับการแก้ของอีก editor','ตะกร้าสินค้าสองเครื่อง: ตรวจ version ก่อนเปลี่ยนจำนวน'],pitfall:'updated_at ของเครื่องลูกค้าไม่ใช่เครื่องมือแก้ conflict ที่เชื่อถือได้ และ last-write-wins อาจทำให้ข้อมูลหาย',
exercises:[num('Server revision=5, Client expected_revision=4 ควรบันทึกสำเร็จกี่แถว?',0,'เงื่อนไข revision ไม่ตรง ต้องคืน conflict/โหลดใหม่ ห้ามเพิ่มเป็น 6 ด้วย snapshot เก่า','ตรวจความเท่ากันก่อนรับ snapshot'),mc('ตรวจเพียง x/y อยู่ในห้องพอหรือไม่?',['พอเพราะ Client มี prefab','ต้องตรวจ instance ownership และการวางซ้ำด้วย','ตรวจชื่อผู้เล่นก็พอ'],1,'ผู้เล่นอาจส่งรหัสเฟอร์นิเจอร์ของคนอื่นหรือใช้ชิ้นเดิมหลายครั้ง','ตำแหน่งถูกไม่ได้แปลว่ามีของจริง'),order('เรียงวิธีแก้ conflict อย่างรักษางานผู้ใช้',['เก็บ draft ที่ผู้ใช้จัดไว้','โหลด snapshot กับ revision ล่าสุด','แสดงความต่างให้เลือกใช้หรือปรับ draft','ส่งใหม่ด้วย revision ล่าสุดหลังผู้ใช้ตัดสิน'],'ไม่ควรลบทิ้งหรือทับอัตโนมัติ ถ้า merge ไม่มีหลักเกณฑ์อาจสร้างข้อมูลผิด','แยก draft ของผู้ใช้จาก snapshot ที่ยืนยันแล้ว')],refs:['json','locks']
},
{
id:18,part:4,title:'Remote Config และกิจกรรมตามเวลา',duration:60,lab:'config',
lead:'อยากเปลี่ยนระยะปลูกหรือเปิดกิจกรรมโดยไม่ส่ง build ใหม่ทำได้ แต่ถ้า config เสียหรือโหลดไม่ได้ เกมควรยังทำงานอย่างไร และใครมีสิทธิ์เปลี่ยนรางวัล?',
goals:['แยกค่ากลางกับข้อมูลความคืบหน้าผู้เล่น','ใช้ schema_version, cache และ fallback','ให้ Server ตรวจช่วงกิจกรรมและรางวัลเอง'],
sections:[sec('1. Config เป็นนิยามที่เปลี่ยนได้','เก็บ config_key,version,payload,starts_at,ends_at เช่นกิจกรรมฤดูใบไม้ร่วง Client โหลดชื่อและภาพเพื่อแสดง Server อ่านกฎราคาและรางวัลที่มีผลจริง อย่าให้ Client ส่ง reward_multiplier แล้ว Server เชื่อ','Remote Config เปลี่ยนพฤติกรรมที่โค้ดรองรับอยู่แล้ว ไม่สามารถเสกชนิดระบบที่ Client ไม่มีโค้ดรองรับ หากเพิ่ม schema ใหม่ต้องมี version และเส้นทาง backward compatibility'),sec('2. Cache ลดต้นทุนและ latency','ข้อมูลกลางไม่ต้องโหลดทุก frame เก็บ last-known-good config และเวลา refresh ตามความต้องการ เมื่อเชื่อมต่อไม่ได้ ใช้ค่าเก่าที่ตรวจแล้วหรือค่า default ที่ปลอดภัย UI ควรบอกหากข้อมูลกิจกรรมอาจไม่ล่าสุด','ไม่ใช้ config เก่าบน Client ตัดสินรางวัล Server ต้องตรวจช่วงเวลาและ version ตามกฎ API เพื่อลดความสับสน return config version ที่ Server ใช้ในผล action'),sec('3. Validate ก่อนใช้','ตรวจ schema_version,ชนิดข้อมูล,ช่วงค่า และ fields ที่จำเป็น เช่น duration_seconds เป็น integer >0 multiplier ในขอบเขตที่ตั้งไว้ JSON parse ผ่านไม่ได้หมายความว่าข้อมูลใช้งานได้','หากพบ version ที่ Client ยังไม่รองรับอย่านำมาใช้แบบเดา ให้ fallback และส่ง diagnostic ที่ไม่เปิดเผยข้อมูลส่วนตัว หรือแสดงว่าต้องอัปเดตเกมเมื่อ feature นั้นไม่มี fallback ที่เหมาะสม'),sec('4. เปิดปิดกิจกรรมด้วย Server time','กำหนด starts_at<=now()<ends_at เป็นช่วงแบบครึ่งเปิด เพื่อให้ปลายทางของกิจกรรมสองช่วงไม่ชนกัน ไม่ใช้ timezone เครื่องหรือวันที่ผู้เล่นส่งมาเป็นหลักฐาน','การแก้ config ต้องเป็นผู้ดูแลที่มีสิทธิ์เหมาะสม ทำ staging,ตรวจ diff และ audit การเปลี่ยนค่าที่แจกของมากผิดพลาดเป็นเรื่องระบบเศรษฐกิจ แม้โค้ดไม่เปลี่ยน')],
example:ex('ตัวอย่าง config มี version · JSON',`{\n  "schema_version": 1,\n  "version": 12,\n  "crop_seconds": 300,\n  "event": {\n    "id": "autumn",\n    "starts_at": "2026-10-10T00:00:00Z",\n    "ends_at": "2026-10-17T00:00:00Z"\n  }\n}`,['เวลาเป็นตัวอย่างกิจกรรม ไม่ใช่กิจกรรมที่เผยแพร่จริง','schema_version บอกโครงสร้าง version บอกชุดค่าที่ปรับ','รางวัลต้องตรวจที่ Server แม้ UI cache กิจกรรมไว้']),cases:['ร้านค้า: เปลี่ยนข้อความโปรโมชั่นและช่วงแสดง แต่ราคาจริงคำนวณหลังบ้าน','แอปทดลอง feature: เปิดบางฟีเจอร์ตามกลุ่มที่ Server กำหนด'],pitfall:'การ parse JSON ผ่านไม่ได้รับรอง range หรือ compatibility ของ config',
exercises:[mc('โหลด config ใหม่ไม่ได้และมี last-known-good ควรทำอย่างไร?',['ใช้ config เก่าที่ตรวจแล้วตามนโยบาย fallback','ใช้ JSON ว่างแล้วตั้งรางวัลสุ่ม','เปิดทุกกิจกรรมเสมอ'],0,'fallback ที่ชัดทำให้เกมยังแสดงผลได้ แต่ Server ยังตัดสินกฎและกิจกรรมจริง','ความล้มเหลวของการโหลดไม่ควรขยายสิทธิ์'),mc('เวลา Server ตรง ends_at ของช่วง [start,end) กิจกรรมยัง active หรือไม่?',['active','หมดช่วงแล้ว','ขึ้นกับนาฬิกาผู้เล่น'],1,'ช่วงครึ่งเปิดรวมต้นแต่ไม่รวมปลาย ทำให้ไม่มีช่วงเวลาซ้อนที่ boundary','สัญลักษณ์ ) หมายถึงไม่รวม end'),num('config รุ่นเก็บไว้ version=12 ใหม่ version=13 และ schema รองรับ ควรบันทึก version ใดเป็น last-known-good?',13,'ตรวจ schema และค่าก่อนยอมรับ version ใหม่ ถ้า validation ผิดต้องเก็บ 12 ต่อ','เลขรุ่นใหม่มีประโยชน์เมื่อชุดค่าผ่านตรวจแล้ว')],refs:['json','datetime']
},
{
id:19,part:4,title:'Daily Quest, เขตเวลา และรางวัลครั้งเดียว',duration:70,lab:'quest',
lead:'เควสต์ “คราฟต์เก้าอี้ 3 ครั้งวันนี้” ดูง่าย แต่วันนี้ของเครื่องผู้เล่นกับ Server อาจไม่ตรงกัน และการรับรางวัลจากสองเครื่องอาจเกิดพร้อมกัน',
goals:['กำหนด daily period จาก timezone ของเกม','นับ progress จาก action ที่ตรวจแล้ว','ใช้ unique claim กับ transaction ป้องกันรางวัลซ้ำ'],
sections:[sec('1. กำหนดความหมายของวันนี้','เกมเลือก UTC หรือ timezone คงที่ เช่น Asia/Bangkok แล้ว Server คำนวณ period_key จากเวลาตนเอง ผู้เล่นเที่ยวต่างประเทศหรือเปลี่ยนเวลาเครื่องไม่ควรทำให้รับวันใหม่ได้ทันที','เก็บ period_key เช่นวันที่ตาม timezone เกม ไม่ใช่เพียง last_claimed_at แล้วลบจำนวนชั่วโมงแบบมั่ว ถ้าระบบ reset ตอน 04:00 ต้องเลื่อนจุดแบ่งวันตามกฎก่อนคำนวณ key'),sec('2. นิยามเควสต์กับ progress','quest_definitions เก็บ quest_id,ชนิดงาน,target,reward ส่วน quest_progress เก็บ user_id,quest_id,period_key,count นับเมื่อ RPC craft commit สำเร็จ ไม่ให้ Client ส่ง count=3 หรือ claim ว่าทำเควสต์สำเร็จเอง','Retry ที่คืน receipt เดิมต้องไม่เพิ่ม progress อีกครั้ง จึงเพิ่ม progress ในเส้นทางที่ทำ action ใหม่จริง และรวมใน transaction เดียวกับผลของ action'),sec('3. Claim เป็น transaction','ตรวจผู้เรียกและ period ที่ Server คำนวณ ล็อกตามกฎของเกม ตรวจ progress>=target สร้าง claim ที่ key(user_id,quest_id,period_key) แล้วเพิ่มรางวัล ถ้าส่งพร้อมกัน unique key/lock ต้องกันผลซ้ำ','ถ้า insert claim สำเร็จแต่เพิ่มรางวัลล้มเหลว ให้ rollback ทั้งคู่ ไม่ใช้สอง HTTP request จาก Unity แยก mark claimed กับ add reward เพราะเน็ตหลุดระหว่างกลางทำให้สถานะผิด'),sec('4. เปลี่ยนเควสต์ระหว่างวัน','ถ้าเปลี่ยน target 3 เป็น 5 กลางวัน ผู้เล่นที่เห็นกฎเก่าควรถูกปฏิบัติอย่างไร เลือก snapshot definitions ต่อ period หรือ version ที่ Server อ้างอยู่ให้ชัด ผล claim บอกกฎและ period ที่ใช้ได้','ลำดับ client UI อาจอัปเดตช้าได้ แต่ Server ต้องเป็นผู้คำนวณ claimable เวลาและ progress ไม่ใช่ใช้การซ่อนปุ่มรับรางวัลเป็นการป้องกันหลัก')],
example:ex('วันของเกมและ unique claim · PostgreSQL',`select timezone('Asia/Bangkok', now())::date as period_key;\n\ncreate table public.quest_claims (\n  user_id uuid references public.profiles(user_id),\n  quest_id text not null, period_key date not null,\n  claimed_at timestamptz not null default now(),\n  primary key(user_id,quest_id,period_key)\n);\n-- ตรวจ progress + insert claim + เพิ่มรางวัลใน RPC transaction เดียว`,['timezone() แปลง instant ก่อนตัดเป็นวันที่ของเกม','PK รวมทั้งผู้เล่น เควสต์ และวัน','ตารางนี้ต้อง RLS และไม่เปิด direct writes ให้ผู้เล่น']),cases:['ระบบคูปอง: หนึ่งสิทธิ์ต่อสมาชิกต่อ campaign period','แอป habit: บันทึกหนึ่งครั้งต่อวันที่นิยามไว้และจัดการเปลี่ยน timezone อย่างชัดเจน'],pitfall:'progress ที่ Client รายงานเองไม่ใช่หลักฐาน และ request ID อย่างเดียวไม่แทน unique claim ต่อวัน',
exercises:[mc('ควรเพิ่ม progress ของ craft quest เมื่อไร?',['ตอนกดปุ่มใน Unity','เมื่อ Server ทำ action ใหม่สำเร็จ','ทุกครั้งที่ retry ได้ response'],1,'เฉพาะ action ที่ตรวจและบันทึกจริง ส่วน retry receipt ไม่ใช่ craft ใหม่','แยก click, request และ action ที่มีผลจริง'),mc('PK สำหรับรับเควสต์รายวันควรเป็นอะไร?',['user_id อย่างเดียว','(user_id,quest_id,period_key)','claimed_at ของเครื่อง Client'],1,'ผู้เล่นรับได้หลายเควสต์หลายวัน แต่รับเควสต์เดียววันเดิมซ้ำไม่ได้','key ต้องตรงกับขอบเขตคำว่าได้ครั้งเดียว'),num('UTC เวลา 18:00 วันที่ 10 ต.ค. เมื่อ timezone เกม UTC+7 วันที่ของ period เป็นวันที่เท่าไร?',11,'18:00+7 ชั่วโมง=01:00 ของวันที่ 11 ต้องแปลงก่อนตัด date','บวก 7 ชั่วโมงแล้วตรวจว่าข้ามเที่ยงคืนหรือไม่')],refs:['datetime','constraints','locks']
},
{
id:20,part:5,title:'ก่อนปล่อยจริง: ต้นทุน สิทธิ์ Backup และการดูแล',duration:75,lab:'budget',
lead:'Free Tier เป็นพื้นที่เริ่มต้น ไม่ใช่หลักฐานว่ารองรับผู้เล่นจำนวนหนึ่งได้แน่นอน จำนวน request,ข้อมูลที่ส่ง และรูปแบบการเล่นเป็นตัวกำหนดต้นทุนและภาระงาน',
goals:['ประมาณการใช้งานจากสมมติฐานที่ตรวจได้','ตรวจเส้นทางสิทธิ์และการผิดกฎ','วาง backup, restore และสังเกตความผิดปกติ'],
sections:[sec('1. วัดแทนเดาจากจำนวนผู้เล่น','request/เดือน≈DAU×sessions/วัน×requests/session×วัน แต่ MAU ไม่เท่ากับ DAU และจำนวน request ไม่ได้แปลงเป็นราคาโดยตรงเสมอ ดู quota ของบริการที่ใช้ เช่น egress,DB size,compute,Auth,Edge และ Realtime','Database RPC ไม่ใช่ Edge invocation ถ้าไม่มี Edge Function ไม่เอา RPC ทุกครั้งไปเทียบโควตา Edge จำนวน request มากยังใช้ compute และ egress ต้องดู query และ index ตามงานจริง ตัว calculator ด้านล่างเป็นการประมาณข้อมูลออก ไม่ใช่ใบเสนอราคา'),sec('2. ลดงานโดยไม่ทำลายกฎ','อ่าน snapshot ตอนเปิดหรือหลัง action cache catalog/config ที่เปลี่ยนช้า และใช้ pagination สำหรับประวัติ ไม่ส่ง Layout ทุก frame ใช้ timer ที่ Client ประมาณและ Server ตรวจตอน action แทน poll ทุกวินาที','500 MB อาจรองรับผู้เล่นได้มากหรือน้อยตามแถว inventory,receipts,index และข้อมูลอื่น ให้ใส่จำนวนรายการต่อคนแล้ววัดขนาดจริง อย่ารับประกันจากข้อมูลโปรไฟล์เพียงอย่างเดียว'),sec('3. ตรวจสิทธิ์ด้วยผู้เรียกจริง','ลองไม่มี session,A อ่าน B,A แก้ quantity โดยตรง,A ปลอม user_id,คราฟต์ทรัพยากรไม่พอ,สองคำขอพร้อมกัน และ retry request เดิม ตรวจผลฐานข้อมูลหลังแต่ละกรณี ไม่เพียงดูว่า UI แสดง error','ใช้ publishable key และ JWT ของ A/B เพื่อทดสอบ RLS Secret key อยู่เฉพาะ backend ที่ควบคุมได้ ทำ rate limit/abuse protection ตามเส้นทาง โดยเฉพาะสร้าง Guest และ action ที่ใช้ทรัพยากรบริการ'),sec('4. Backup ที่กู้ได้และงานดูแล','สำรองข้อมูลพร้อมกฎการเก็บ ลอง restore ในสภาพแวดล้อมแยกและตรวจข้อมูลสัมพันธ์ ไม่ถือว่าไฟล์ backup มีอยู่แล้วกู้ได้แน่นอน DB backup กับไฟล์ Storage/Auth/config อาจมีขอบเขตต่างกัน ต้องอ่านวิธีของแพลตฟอร์ม','self-host หมายถึงดูแล OS,อัปเดต,HTTPS,backup,monitoring และ uptime เอง เอกสาร Supabase ระบุทรัพยากรขั้นต่ำของ stack ไม่ควรสรุปว่า VPS ราคาถูกทุกตัวใช้ production ได้หรือย้ายทันทีโดยไม่มีงานเพิ่ม'),sec('5. ทำให้หาสาเหตุได้','เก็บ request ID,action type,status,duration และ error code ที่จำเป็น โดยไม่เก็บ password หรือ token Dashboard ช่วยดู DB/query และ error แต่ต้องรู้ว่ากำลังวัดจำนวนคำขอ ความผิดพลาด หรือ latency','ก่อน migration ที่เสี่ยง ใช้ staging ตรวจ compatibility และวาง roll-forward/rollback ของ schema กับข้อมูล อย่าปล่อยให้ข้อมูลที่แปลงแล้วใช้กับโค้ดเก่าไม่ได้โดยไม่มีแผน')],
example:ex('ประมาณการใช้งาน · สูตร',`requests_month = DAU × sessions_per_day × requests_per_session × 30\negress_GB ≈ requests_month × response_KB / 1,000,000\n\nตัวอย่าง: 100 × 2 × 15 × 30 = 90,000 requests\nresponse เฉลี่ย 2 KB ≈ 0.18 GB (หน่วย decimal)\nไม่รวม header, retry,ไฟล์,Realtime และการใช้งานอื่น`,['นี่เป็นสมมติฐานเพื่อเรียนการประมาณ ไม่ใช่ราคาที่รับประกัน','ค่าเฉลี่ยซ่อน burst และช่วงผู้เล่นเข้าเยอะพร้อมกัน','เทียบ quota ปัจจุบันจากหน้า billing ของบริการจริง']),cases:['ระบบรายงานบริษัท: query หนักหนึ่งครั้งอาจใช้ compute มากกว่า query สั้นหลายครั้ง','แอปแชร์ภาพ: egress/Storage อาจเป็นต้นทุนหลักมากกว่าตารางผู้ใช้'],pitfall:'Backup ที่ไม่เคย restore และ RLS ที่ทดสอบด้วย admin อย่างเดียวให้ความมั่นใจที่ไม่มีหลักฐาน',
exercises:[num('DAU=100,วันละ 2 session,session ละ 15 request,30 วัน รวมกี่ request?',90000,'คูณตามสมมติฐาน 100×2×15×30 ยังไม่รวม retry และคำขอระบบอื่น','นับรายวันก่อนแล้วคูณ 30'),mc('เรียก Database RPC โดยตรง 100 ครั้ง ต้องนับเป็น Edge invocation 100 ครั้งไหม?',['ใช่เสมอ','ไม่ใช่ หากไม่ได้เรียก Edge Function','ไม่มีต้นทุนทรัพยากรใด ๆ'],1,'RPC ทำงานในฐานข้อมูลโดยตรง แต่ยังใช้ DB compute และข้อมูลออก','แยกเส้นทางเรียกบริการก่อนนับ quota'),order('เรียงหลักฐานว่ากู้ระบบได้',['สำรองข้อมูลตามขอบเขตที่กำหนด','restore ลงสภาพแวดล้อมแยก','ตรวจ row count,สัมพันธ์และไฟล์ที่จำเป็น','ลอง Login และ action สำคัญ','บันทึกวิธีกู้และเวลาที่ใช้'],'การมีไฟล์เป็นเพียงขั้นแรก ต้องพิสูจน์ระบบที่ restore ใช้งานได้ตามขอบเขต','อย่าทดลอง restore ทับ production เพื่อฝึก')],refs:['billing','selfhost','rls']
},
{
id:21,part:5,title:'Final Project: ออกแบบ Cozy Shelter ทั้งระบบ',duration:100,lab:'capstone',
lead:'บทสุดท้ายไม่มีแนวคิดใหม่ก้อนใหญ่ คุณจะเลือกกฎของระบบแล้วทดสอบกับสถานการณ์ที่ทำให้เกมผิดพลาดง่าย ใช้ผลอธิบายว่าทำไมแต่ละชั้นต้องมีหน้าที่ของตัวเอง',
goals:['เชื่อม Auth,สิทธิ์,กฎเกม,เวลาและการเขียนพร้อมกัน','ออกแบบ API ที่คืนข้อมูลให้ Unity ใช้ต่อได้','แยกผลทดสอบแบบจำลองกับหลักฐานจากระบบจริง'],
sections:[sec('1. เส้นทางผู้เล่นครบวงจร','เริ่ม restore session ถ้ามี ถ้าไม่มีค่อยเลือก Guest/Login รับ user ID เดิมเมื่อผูกบัญชี โหลด Profile,Inventory,Shelter,Layout และ config แล้วให้ UI แสดงสถานะตาม response','Plant,Craft,StartUpgrade,CompleteUpgrade และ ClaimQuest เป็น action ที่ Server ตรวจ กิจกรรมที่เป็นภาพอย่างเดียวไม่ต้องบันทึกทุก frame หลังสำเร็จ Client ใช้ snapshot/revision ที่ได้รับ'),sec('2. แผนข้อมูลที่ต้องอธิบายได้','profiles ผูก auth.users; item_catalog นิยามชนิด; user_inventory ใช้คู่ owner/item; plots เก็บ ready_at และ harvested; shelters เก็บ state/target; layouts เก็บ revision; action_receipts จำผล; quest_progress/claims ใช้ period','ตารางกลางอ่านได้ตาม role ที่กำหนด ข้อมูลผู้เล่นอ่านเฉพาะ owner ข้อมูลเศรษฐกิจเขียนผ่าน validated RPC ตารางใดแก้จาก Client ได้ให้กำหนดคอลัมน์และ policy ชัด'),sec('3. แบบฝึกโปรเจกต์ในเว็บ','ตัวทดลองนี้ให้คุณเลือกวิธีตัดสินเวลา การเขียน inventory การควบคุม concurrency การ retry และ revision แล้วรันชุดเหตุการณ์ ระบบรายงานว่ากฎที่เลือกทำให้เกิดผลผิดในกรณีใด','นี่เป็น design simulator ที่ตรวจทางเลือกตามแบบจำลอง ไม่ใช่ผลทดสอบ Supabase จริง ใช้มันซ้อม reasoning ก่อนนำ SQL และ Unity ไปสร้างระบบ ต้องทดสอบ RLS,lock และ migration ในฐานข้อมูลจริงอีกขั้น'),sec('4. เกณฑ์ตรวจโปรเจกต์จริง','ผู้เล่น A อ่านหรือแก้ข้อมูล B ไม่ได้ Direct write เพิ่ม quantity ต้องถูกปฏิเสธ คราฟต์พร้อมกันต้องไม่ใช้วัตถุดิบเกินที่มี Retry เดิมต้องไม่หักอีกครั้ง Client time ไม่ปลดล็อกเก็บเกี่ยว และ claim วันเดียวไม่แจกซ้ำ','Layout เก่าต้อง conflict,session ที่ refresh สำเร็จต้องรักษาผู้เล่นเดิม,config เสียต้อง fallback อย่างควบคุม และเมื่อ restore backup ต้องกลับมาอ่าน/ทำ action ได้ เก็บ input,response และผล DB เพื่อเป็นหลักฐาน'),sec('5. ต่อไปเมื่อเกมโต','เริ่มวัด bottleneck จริงก่อนเปลี่ยน architecture อาจเพิ่ม batching,cache,queue หรือ service ภายนอกเมื่อ SQL transaction ไม่เหมาะกับงานนั้น อย่าใช้ Server แบบเรียลไทม์สำหรับ cozy persistence หากยังไม่มีความต้องการ multiplayer realtime','สิ่งที่ต่อยอดไปงานอื่นได้คือ relational modeling,HTTP,Auth,สิทธิ์,transaction,idempotency และ observability ใช้ได้กับร้านค้า ระบบจอง เว็บสมาชิก และเครื่องมือภายใน')],
example:ex('API contract ของหนึ่ง action · JSON',`// request\n{ "request_id": "<UUID เดิมเมื่อ retry>", "recipe_id": "chair" }\n\n// response ตัวอย่าง หลัง Server commit\n{\n "action_id": "<UUID>", "replayed": false,\n "inventory": [{"item_id":"wood","quantity":4}],\n "server_now": "2026-10-10T08:00:00Z",\n "revision": 7\n}`,['ขอบเขต inventory response ต้องชัดว่าเป็น snapshot หรือ delta','replayed ช่วย debug ไม่ใช่สิ่งที่ Client ใช้เพิ่มของซ้ำ','เวลาที่แสดงเป็นตัวอย่าง ไม่ใช่เวลาของระบบจริง']),cases:['ร้านค้าออนไลน์: inventory,order,receipt และ config ราคาใช้หลักเดียวกัน','ระบบจอง: identity,ownership,availability,lock และ expiry ต่อกันเป็นเส้นทางเดียว'],pitfall:'ผ่าน simulator ไม่รับรอง production การตรวจสิทธิ์และ concurrency ต้องทำกับบริการจริงตามผู้เรียกจริง',
exercises:[mc('ระบบใดเป็นหลักฐานว่าผู้เล่นรับเควสต์ได้?',['ปุ่ม UI แสดงสีเขียว','Server ตรวจ progress และ period ที่เก็บ','Client ส่ง count=3'],1,'UI เป็นการแสดงผล Server ใช้ความคืบหน้าจาก action ที่ตรวจแล้วและวันที่นิยามไว้','ใครควบคุมหลักฐานที่ใช้ตัดสิน'),mc('สิ่งใดแยกหน้าที่ถูกต้อง?',['Auth ตรวจตัวตน,RLS จำกัดข้อมูล,RPC ตรวจ action','Auth ทำทุกอย่าง','RLS คำนวณสูตรคราฟต์เอง'],0,'แต่ละชั้นทำงานร่วมกัน การขาดชั้นหนึ่งเปิดปัญหาคนละแบบ','ทบทวนคำถาม ใคร /ข้อมูลใด /ทำอะไรได้'),order('เรียงการเพิ่มระบบใหม่ เช่นขายไอเทม',['กำหนดกฎและสิ่งที่ Client ส่งได้','ออกแบบข้อมูล,key,สิทธิ์และ API','เขียน transaction และป้องกันผลซ้ำ','ตรวจกรณีผิดกฎพร้อมกันและเน็ตหลุด','เชื่อม Unity และวัดการใช้งาน'],'เริ่มจากสัญญาและกฎก่อน UI แล้วใช้หลักฐานตรวจสิ่งที่เขียน','นำทุกบทมาใช้กับ action ใหม่ ไม่ใช่เพิ่ม endpoint โดยไม่มีสัญญา')],refs:['functions','rls','locks','sessions']
}
);
